(function () {
// Neue Transferfälle (nicht aus Altklausuren/Übungsfällen), je 6 Antworten
const W=(window.WPRK_LONG=window.WPRK_LONG||[]);
const L=[{"topic": "vs", "sv": "Galeristin G bietet dem Sammler S am Montag per Brief eine Skulptur für 4.000 € an: „An dieses Angebot halte ich mich bis einschließlich Freitag gebunden.“ S schreibt am Donnerstag einen Annahmebrief, der wegen eines normalen Postlaufs erst am Samstag bei G eingeht. G reagiert nicht und verkauft die Skulptur am Montag an einen anderen Kunden. S verlangt Lieferung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Ein Vertrag besteht, weil S die Annahme noch innerhalb der Frist abgesendet hat (§§ 147, 148).", "Falsch. Für die Frist kommt es auf den Zugang der Annahme an (§ 130 I 1), nicht auf die Absendung."], ["Ein Vertrag besteht, weil G auf die verspätete Annahme hätte reagieren müssen und ihr Schweigen als Zustimmung gilt (§ 149).", "Falsch. § 149 greift nur, wenn die Annahme bei regelmäßiger Beförderung rechtzeitig angekommen wäre und das für G erkennbar war. Hier lief die Post normal."], ["Kein Vertrag: Die Annahme kam nach Fristablauf an und gilt nur als neues Angebot, das G nicht angenommen hat; ihr Schweigen ändert daran nichts (§ 150 I).", "Richtig. Das Angebot erlosch mit Ablauf des Freitags (§ 148). Die verspätete Annahme ist ein neuer Antrag; Schweigen darauf ist keine Annahme."], ["Kein Vertrag, weil G ihr Angebot durch den Verkauf an den anderen Kunden schlüssig widerrufen hat (§ 130 I 2).", "Falsch. Ergebnis richtig, Begründung falsch: Ein Widerruf müsste S zugehen. Das Angebot war ohnehin schon mit Ablauf der Frist erloschen."], ["Ein Vertrag besteht, weil eine Annahmefrist „bis Freitag“ erst mit Ablauf des folgenden Werktags endet (§§ 188, 193).", "Falsch. § 193 verschiebt nur ein Fristende, das auf einen Samstag, Sonntag oder Feiertag fällt. Hier endete die Frist am Freitag."], ["Ein Vertrag besteht, G kann ihn aber anfechten, weil sie sich über den Zugang der Annahme geirrt hat (§ 119 I).", "Falsch. Es gibt schon keinen Vertrag. Außerdem ist eine Fehlvorstellung über Zugangszeiten kein Inhalts- oder Erklärungsirrtum."]], "id": "P5-0", "tag": "Neu · Transfer", "neu": true}, {"topic": "vs", "sv": "Die Möbelbau GmbH (M) und die Holzhandel GmbH (H) einigen sich am Telefon über die Lieferung von 50 m³ Eichenholz zu 900 €/m³. Über Zahlungsziel und Gerichtsstand sprechen sie nicht. Am nächsten Morgen schickt H ein als „Auftragsbestätigung“ überschriebenes Schreiben: „Wir bestätigen unser Telefonat: 50 m³ Eiche, 900 €/m³, zahlbar innerhalb von 14 Tagen nach Lieferung.“ M liest das Schreiben, reagiert aber nicht. Nach der Lieferung meint M, ein Zahlungsziel sei nie vereinbart worden, es gelte die übliche Fälligkeit nach 30 Tagen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Das Zahlungsziel ist nicht vereinbart, weil Schweigen im Rechtsverkehr nie als Willenserklärung gilt (§§ 145 ff.).", "Falsch. „Nie“ stimmt nicht: Unter Kaufleuten kann Schweigen auf ein kaufmännisches Bestätigungsschreiben als Zustimmung gelten (Handelsbrauch, § 346 HGB)."], ["Das Zahlungsziel ist nicht vereinbart, weil ein Bestätigungsschreiben nur wirkt, wenn der Empfänger es gegenzeichnet.", "Falsch. Gerade das ist der Kern des Bestätigungsschreibens: Wirkung entsteht ohne Gegenzeichnung, wenn der Empfänger nicht unverzüglich widerspricht."], ["Das Zahlungsziel ist nicht vereinbart, weil es sich um eine Auftragsbestätigung handelt, die als neues Angebot erst angenommen werden muss (§ 150 II).", "Falsch. Auf die Bezeichnung kommt es nicht an. Das Schreiben gibt ein bereits geschlossenes Telefongeschäft wieder und ist deshalb ein Bestätigungsschreiben, keine Annahme mit Änderungen."], ["Das Zahlungsziel ist vereinbart, aber nur, wenn M es in den AGB der H vorher zur Kenntnis nehmen konnte (§ 305 II).", "Falsch. Es geht nicht um AGB, sondern um ein einzelnes Bestätigungsschreiben. § 305 II gilt gegenüber Unternehmern zudem nicht (§ 310 I)."], ["Das Zahlungsziel ist vereinbart, weil M dem kaufmännischen Bestätigungsschreiben nicht unverzüglich widersprochen hat.", "Richtig. Beide sind Kaufleute, Verhandlungen gingen voraus, das Schreiben kam unmittelbar danach und weicht nicht so stark ab, dass H mit Ablehnung rechnen musste. Schweigen gilt als Zustimmung."], ["Das Zahlungsziel ist vereinbart, weil der Inhalt eines Bestätigungsschreibens immer Vertragsinhalt wird, auch wenn er stark abweicht.", "Falsch. „Immer“ ist falsch: Bei erheblichen Abweichungen oder unredlichem Absender wirkt das Schweigen nicht als Zustimmung."]], "id": "P5-1", "tag": "Neu · Transfer", "neu": true}, {"topic": "vs", "sv": "Einkäuferin E der Druckerei D schickt dem Papiergroßhändler P am Dienstag ein Angebot über 200 Paletten Papier per Brief. Am Mittwoch um 8:30 Uhr – kurz nach Beginn der Geschäftszeit – geht bei P eine E-Mail der E ein: „Unser Angebot von gestern ziehen wir zurück.“ Der Brief wird bei P am Mittwoch um 10 Uhr zugestellt. Der zuständige Sachbearbeiter liest beides erst am Nachmittag und schickt sofort eine Annahme.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Kein Vertrag: Der Widerruf ist P vor dem Angebot zugegangen und hat es deshalb verhindert (§ 130 I 2).", "Richtig. Ein Widerruf wirkt, wenn er vorher oder gleichzeitig mit der Erklärung zugeht. Auf das tatsächliche Lesen kommt es nicht an."], ["Ein Vertrag besteht, weil der Sachbearbeiter beide Erklärungen gleichzeitig gelesen hat und dann angenommen hat.", "Falsch. Maßgeblich ist der Zugang (Möglichkeit der Kenntnisnahme unter normalen Umständen), nicht der Zeitpunkt des Lesens. Selbst bei gleichzeitigem Zugang wäre der Widerruf wirksam."], ["Ein Vertrag besteht, weil ein schriftliches Angebot nur schriftlich widerrufen werden kann (§§ 126, 130).", "Falsch. Für Angebot und Widerruf gilt keine Form. Der Widerruf ist auch per E-Mail möglich."], ["Kein Vertrag, weil das Angebot erst mit dem Lesen am Nachmittag zugegangen ist und der Widerruf schon vorher vorlag.", "Falsch. Ergebnis richtig, Begründung falsch: Der Brief ging bereits um 10 Uhr zu, als er in den Machtbereich von P gelangte und während der Geschäftszeit mit Kenntnisnahme zu rechnen war."], ["Ein Vertrag besteht, weil der Widerruf eines Angebots nur bis zur Absendung des Angebots möglich ist (§ 145).", "Falsch. Ein Widerruf ist bis zum Zugang des Angebots möglich (§ 130 I 2). Die Absendung ist nicht maßgeblich."], ["Kein Vertrag, weil E das Angebot als Angestellte ohnehin nicht ohne Prokura abgeben durfte (§ 49 HGB).", "Falsch. Einkäufer haben regelmäßig Handlungsvollmacht für solche Geschäfte (§ 54 HGB); eine Prokura ist nicht nötig. Der Vertrag scheitert am Widerruf."]], "id": "P5-2", "tag": "Neu · Transfer", "neu": true}, {"topic": "vs", "sv": "Im Schaufenster des Elektrohändlers H steht eine Espressomaschine mit dem Preisschild „49 €“. Richtig wären 490 €; eine Aushilfe hat die Null vergessen. Kunde K kommt in den Laden, nimmt eine originalverpackte Maschine aus dem Regal und legt sie an der Kasse mit den Worten „für 49 €, wie im Schaufenster“ hin. Die Kassiererin bemerkt den Fehler und lehnt einen Verkauf zu diesem Preis ab. K verlangt die Maschine für 49 €.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K hat Anspruch auf die Maschine für 49 €, weil die Preisauszeichnung ein verbindliches Angebot an jedermann ist (§ 145).", "Falsch. Die Ware im Schaufenster ist eine invitatio ad offerendum: Der Händler will sich nicht gegenüber beliebig vielen Kunden binden."], ["Ein Vertrag zu 49 € ist zustande gekommen; H kann ihn aber wegen Erklärungsirrtums anfechten und schuldet K dann den Vertrauensschaden (§§ 119 I, 122).", "Falsch. Es gibt nichts anzufechten, weil kein Vertrag zustande gekommen ist. § 122 setzt eine wirksame Anfechtung voraus."], ["Ein Vertrag zu 490 € ist zustande gekommen, weil der wirkliche Wille des H maßgeblich ist (§ 133).", "Falsch. K wollte erkennbar nur zu 49 € kaufen. Ohne übereinstimmende Erklärungen gibt es keinen Vertrag – erst recht nicht zu einem Preis, den K nie angeboten hat."], ["Kein Vertrag: K hat an der Kasse ein Angebot über 49 € abgegeben, das die Kassiererin abgelehnt hat.", "Richtig. Das Schaufenster ist nur eine Aufforderung zur Abgabe von Angeboten. Das Angebot kommt vom Kunden, der Händler kann es ablehnen."], ["Kein Vertrag, weil Kaufverträge über Waren ab 100 € Marktwert nur schriftlich geschlossen werden können.", "Falsch. Kaufverträge sind formfrei. Der Vertrag scheitert an der fehlenden Annahme."], ["K hat Anspruch auf die Maschine für 49 €, weil falsche Preisangaben gegen das Verbraucherschutzrecht verstoßen und deshalb zugunsten des Kunden gelten.", "Falsch. Ein solcher Anspruch existiert nicht. Wettbewerbsrechtliche Folgen einer falschen Preisangabe ändern nichts daran, dass kein Vertrag geschlossen wurde."]], "id": "P5-3", "tag": "Neu · Transfer", "neu": true}, {"topic": "vs", "sv": "V will ihr Wiesengrundstück am Ortsrand (Flurstück 117) an K verkaufen. Beide haben das Grundstück gemeinsam besichtigt und sind sich einig, dass genau diese Wiese verkauft wird. Im notariellen Kaufvertrag wird versehentlich „Flurstück 171“ eingetragen – ein Waldstück, das V ebenfalls gehört. Der Fehler fällt erst nach der Beurkundung auf. V meint nun, es sei gar kein wirksamer Vertrag zustande gekommen, weil das gewollte Grundstück nicht beurkundet sei.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Ein Vertrag über das Waldstück (171) ist zustande gekommen, weil im Grundstücksrecht allein der beurkundete Wortlaut gilt (§ 311b I 1).", "Falsch. Auch bei beurkundeten Verträgen geht der übereinstimmende wirkliche Wille dem Wortlaut vor (§ 133)."], ["Kein Vertrag, weil die Parteien sich über den Kaufgegenstand nicht geeinigt haben (versteckter Dissens, § 155).", "Falsch. Ein Dissens liegt nicht vor: Beide meinten dasselbe Grundstück. Nur die Bezeichnung war falsch."], ["Ein Vertrag über die Wiese besteht, aber erst, wenn der Notar die Urkunde berichtigt hat; bis dahin ist er schwebend unwirksam.", "Falsch. Eine Berichtigung ist sinnvoll, aber keine Wirksamkeitsvoraussetzung. Einen Schwebezustand sieht das Gesetz hier nicht vor."], ["Der Vertrag über die Wiese ist formnichtig, kann aber durch Auflassung und Eintragung des Flurstücks 117 geheilt werden (§ 311b I 2).", "Falsch. Nach der Rechtsprechung ist der Vertrag über das wirklich Gewollte schon formwirksam; auf eine Heilung kommt es nicht an."], ["V kann den Vertrag über das Waldstück wegen Erklärungsirrtums anfechten; danach muss neu beurkundet werden (§ 119 I).", "Falsch. Ein Vertrag über das Waldstück besteht gar nicht, weil keine Partei es wollte. Eine Anfechtung geht ins Leere."], ["Ein formwirksamer Vertrag über die Wiese (117) ist zustande gekommen; die Falschbezeichnung schadet nicht.", "Richtig. Falsa demonstratio non nocet: Gilt das übereinstimmend Gewollte, ist nach dem BGH auch die Form des § 311b I gewahrt, obwohl die Urkunde falsch bezeichnet."]], "id": "P5-4", "tag": "Neu · Transfer", "neu": true}, {"topic": "lst", "sv": "Die IT-Firma I GmbH installiert für die Steuerkanzlei S ein Netzwerk und schickt am 2. März die Rechnung über 6.000 €. Ein Zahlungsdatum ist weder vereinbart noch in der Rechnung angegeben. S zahlt nicht und wird auch nicht gemahnt. Am 20. April verlangt I Verzugszinsen und eine Verzugspauschale.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["S ist nicht in Verzug, weil ohne Mahnung und ohne kalendermäßig bestimmte Leistungszeit kein Verzug eintritt (§ 286 I, II).", "Falsch. § 286 III ist ein eigener Verzugstatbestand für Entgeltforderungen: 30 Tage nach Fälligkeit und Zugang der Rechnung – ohne Mahnung."], ["Verzug 30 Tage nach Rechnungszugang; I kann 9 Prozentpunkte über dem Basiszins und 40 € Pauschale verlangen (§§ 286 III, 288 II, V).", "Richtig. Bei Entgeltforderungen ohne Verbraucherbeteiligung tritt Verzug nach 30 Tagen ein; Zinssatz und Pauschale gelten, weil S kein Verbraucher ist."], ["S ist in Verzug, aber Zinsen gibt es nur in Höhe von 5 Prozentpunkten über dem Basiszinssatz, weil S nicht Kaufmann ist (§ 288 I).", "Falsch. Der höhere Zinssatz gilt bei allen Rechtsgeschäften, an denen kein Verbraucher beteiligt ist (§ 288 II). Kaufmannseigenschaft ist nicht nötig; S handelt als Unternehmerin."], ["S ist erst in Verzug, wenn I ausdrücklich auf die Folgen des Ausbleibens der Zahlung hingewiesen hat (§ 286 III 1 Hs. 2).", "Falsch. Dieser Hinweis ist nur gegenüber Verbrauchern erforderlich. S ist eine Steuerkanzlei, also Unternehmerin."], ["S ist schon seit Zugang der Rechnung in Verzug, weil die Forderung damit sofort fällig wurde (§ 271 I).", "Falsch. Fälligkeit allein begründet noch keinen Verzug. Ohne Mahnung tritt er hier erst 30 Tage nach Zugang der Rechnung ein."], ["S ist in Verzug, I kann die Pauschale von 40 € aber nur verlangen, wenn ihm tatsächlich Mahnkosten in dieser Höhe entstanden sind (§ 288 V).", "Falsch. Die Pauschale ist gerade unabhängig von konkreten Kosten. Sie wird nur auf einen weitergehenden Schadensersatz angerechnet (§ 288 V 2)."]], "id": "P5-5", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Verbraucher K kauft bei Händler H ein neues E-Bike für 2.800 €. Nach drei Wochen versagt der Motor wegen eines Herstellungsfehlers. K hat keine Lust auf Wartezeiten und lässt das Rad sofort, ohne H zu informieren, in einer Fachwerkstatt für 450 € reparieren. Danach verlangt er die 450 € von H, hilfsweise wenigstens die Kosten, die H selbst für eine Reparatur erspart hat.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K kann die 450 € verlangen, weil H den Mangel zu vertreten hat und K als Verbraucher keine Frist setzen muss (§§ 280 I, 475d).", "Falsch. § 475d macht die Frist nur entbehrlich, wenn der Unternehmer über den Mangel unterrichtet wurde und nicht innerhalb angemessener Zeit nacherfüllt. K hat H gar nicht informiert."], ["K kann die 450 € verlangen, weil er den Mangel nur so beseitigen konnte und H dadurch Arbeit erspart hat (§ 439 II).", "Falsch. § 439 II verpflichtet den Verkäufer, die Kosten seiner eigenen Nacherfüllung zu tragen. Einen Ersatz für Fremdreparaturen ohne vorherige Gelegenheit zur Nacherfüllung gibt er nicht."], ["K kann die Kosten verlangen, die H für die Reparatur erspart hat, weil H sonst bereichert wäre (§ 326 II 2 analog).", "Falsch. Der BGH lehnt diese Analogie ab: Sonst würde der Vorrang der Nacherfüllung umgangen."], ["K kann nichts verlangen, weil er H vor der Selbstvornahme keine Gelegenheit zur Nacherfüllung gegeben hat.", "Richtig. Das Recht des Verkäufers zur zweiten Andienung ist vorrangig. Wer selbst repariert, ohne dem Verkäufer Gelegenheit zu geben, verliert den Kostenersatz (BGH)."], ["K kann nichts verlangen, weil Motoren von E-Bikes Verschleißteile sind und deshalb kein Sachmangel vorliegt (§ 434).", "Falsch. Ein Ausfall nach drei Wochen wegen eines Herstellungsfehlers ist kein Verschleiß, sondern ein Sachmangel."], ["K kann die 450 € verlangen, aber nur zur Hälfte, weil er zu einem Teil selbst schuld ist (§ 254).", "Falsch. Es gibt keinen geteilten Anspruch. Am fehlenden Nacherfüllungsverlangen scheitert der Ersatz ganz."]], "id": "P5-6", "tag": "Neu · Transfer", "neu": true}, {"topic": "lst", "sv": "Juwelier J verkauft K einen Goldring für 1.200 €, Abholung in einer Woche. Am nächsten Tag zeigt J den Ring auf einem Ausflug einem Freund und lässt ihn dabei unachtsam vom Steg in einen 30 m tiefen See fallen. Eine Bergung mit Tauchern würde rund 40.000 € kosten. K verlangt Übergabe des Rings, hilfsweise Schadensersatz; ein vergleichbarer Ring würde ihn 1.500 € kosten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["J muss den Ring bergen lassen, weil er den Verlust selbst verschuldet hat und ihm deshalb jeder Aufwand zuzumuten ist (§ 275 II 2).", "Falsch. Bei Vertretenmüssen sind größere Anstrengungen zumutbar, aber nicht jeder Aufwand. 40.000 € für einen Ring von 1.200 € bleiben ein grobes Missverhältnis."], ["J ist kraft Gesetzes von der Leistungspflicht frei, weil die Bergung tatsächlich unmöglich ist (§ 275 I).", "Falsch. Die Bergung ist möglich, nur extrem teuer. Das ist ein Fall des § 275 II, der eine Einrede gibt, keine automatische Befreiung."], ["J kann die Leistung verweigern; K muss nicht zahlen und hat auch keinen Schadensersatzanspruch, weil J nicht absichtlich handelte.", "Falsch. Für Schadensersatz genügt Fahrlässigkeit (§ 276 I). Unachtsames Hantieren am Steg ist fahrlässig."], ["J kann die Leistung verweigern, muss K aber die Bergungskosten erstatten, damit K selbst tauchen lassen kann (§ 285).", "Falsch. § 285 betrifft einen Ersatz, den der Schuldner für den Gegenstand erlangt hat. Bergungskosten sind kein solches Surrogat."], ["J kann die Leistung verweigern; K muss nicht zahlen und kann 300 € Schadensersatz statt der Leistung verlangen (§§ 275 II, 283).", "Richtig. Grobes Missverhältnis → Einrede (§ 275 II). Gegenleistung entfällt (§ 326 I). J hat fahrlässig gehandelt → Schadensersatz: 1.500 € Wert minus 1.200 € ersparter Preis."], ["J kann die Leistung verweigern; K muss trotzdem zahlen, weil die Gefahr mit Vertragsschluss auf ihn übergegangen ist (§ 446).", "Falsch. Die Gefahr geht erst mit der Übergabe über (§ 446 S. 1). Hier gab es keine Übergabe, deshalb entfällt der Kaufpreis (§ 326 I)."]], "id": "P5-7", "tag": "Neu · Transfer", "neu": true}, {"topic": "lst", "sv": "Weinhändler W verkauft dem Restaurantbetreiber R „60 Flaschen Riesling, Jahrgang 2023“ aus seinem großen Lagerbestand. Vereinbart ist Abholung bei W am Freitag um 10 Uhr. W stellt am Donnerstag 60 Flaschen mit R's Namen beschriftet bereit und teilt das R mit. R erscheint am Freitag nicht. In der Nacht auf Samstag brechen trotz ordnungsgemäß gesicherter Türen Diebe ein und stehlen genau diese Kisten. W verlangt den Kaufpreis; R verlangt 60 andere Flaschen aus dem Lager.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["W muss nicht neu liefern und kann den Kaufpreis verlangen (§§ 243 II, 275 I, 326 II 1 Alt. 2).", "Richtig. Konkretisierung → nur noch diese Flaschen geschuldet; durch den Diebstahl unmöglich. R war im Annahmeverzug, W trifft kein Verschulden → Preis bleibt."], ["W muss 60 andere Flaschen liefern, weil bei einer Gattungsschuld Unmöglichkeit ausgeschlossen ist, solange die Gattung vorhanden ist (§ 243 I).", "Falsch. Mit der Konkretisierung (§ 243 II) beschränkt sich die Schuld auf die ausgesonderten Flaschen. Andere Flaschen aus dem Lager sind nicht mehr geschuldet."], ["W muss nicht liefern, kann aber auch keinen Kaufpreis verlangen, weil er die Flaschen nicht übergeben hat (§§ 275 I, 326 I).", "Falsch. § 326 I gilt grundsätzlich, wird aber durch § 326 II 1 Alt. 2 verdrängt: Unmöglichkeit während des Annahmeverzugs des Gläubigers."], ["W muss liefern, weil er im Annahmeverzug für jede Fahrlässigkeit haftet und die Kisten im Laden hätte verschließen müssen (§ 300 I).", "Falsch. Genau umgekehrt: Im Annahmeverzug haftet der Schuldner nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I). Die Türen waren ordnungsgemäß gesichert."], ["W kann den Kaufpreis nur verlangen, wenn er R vorher ein tatsächliches Angebot an dessen Restaurant gemacht hat (§ 294).", "Falsch. Bei einer Holschuld mit vereinbartem Abholtermin genügt das Bereitstellen; ein Angebot ist bei kalendermäßig bestimmter Mitwirkung sogar entbehrlich (§ 296)."], ["W muss nicht liefern; den Kaufpreis bekommt er nur zur Hälfte, weil keine Partei den Diebstahl zu vertreten hat.", "Falsch. Eine Teilung kennt das Gesetz nicht. § 326 II 1 Alt. 2 erhält den vollen Kaufpreisanspruch."]], "id": "P5-8", "tag": "Neu · Transfer", "neu": true}, {"topic": "lst", "sv": "Kunstschreiner K hat beim Händler H eine Hobelmaschine gekauft. H liefert nicht. K setzt eine angemessene Frist, die erfolglos abläuft. Am 1. Juli schreibt K an H: „Ich verlange jetzt Schadensersatz statt der Leistung.“ Am 3. Juli steht H mit der Maschine vor der Tür. K hat inzwischen bemerkt, dass eine Ersatzmaschine viel teurer wäre, und möchte die Maschine nun doch nehmen; H will sie nicht mehr übergeben.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K kann die Maschine verlangen, weil der Erfüllungsanspruch erst mit Zahlung des Schadensersatzes erlischt (§ 362).", "Falsch. § 281 IV knüpft das Erlöschen bereits an das Verlangen des Schadensersatzes, nicht an dessen Zahlung."], ["K kann die Maschine verlangen, weil er zwischen Erfüllung und Schadensersatz bis zum Ende des Prozesses frei wählen kann (§ 262).", "Falsch. § 262 regelt die Wahlschuld, nicht das Verhältnis von Leistung und Schadensersatz. Mit dem Schadensersatzverlangen ist die Wahl getroffen."], ["K kann die Maschine nicht mehr verlangen: Mit dem Schadensersatzverlangen ist der Leistungsanspruch erloschen (§ 281 IV).", "Richtig. Das Verlangen ist eine Gestaltungserklärung; danach bleibt K nur der Schadensersatz."], ["K kann die Maschine nicht mehr verlangen, weil er mit Fristablauf automatisch vom Vertrag zurückgetreten ist (§ 323 I).", "Falsch. Ein Rücktritt tritt nie automatisch ein, er muss erklärt werden (§ 349). Der Leistungsanspruch ist aus einem anderen Grund erloschen."], ["K kann die Maschine verlangen, weil H durch die Lieferung den Verzug geheilt und das Schadensersatzverlangen damit gegenstandslos gemacht hat (§ 286).", "Falsch. Eine verspätete Leistung lässt das bereits erklärte Schadensersatzverlangen nicht wieder entfallen."], ["K kann die Maschine nicht mehr verlangen, weil H wegen Ablaufs der Frist ein Rücktrittsrecht hatte, das er mit der Weigerung ausgeübt hat (§ 323).", "Falsch. Ein Rücktrittsrecht wegen eigener Nichtleistung hat der säumige Schuldner nicht. Ausschlaggebend ist § 281 IV."]], "id": "P5-9", "tag": "Neu · Transfer", "neu": true}, {"topic": "lst", "sv": "Möbelhaus M soll der Kundin K am 12. Mai um 9 Uhr ein Sofa liefern. Die Monteure stehen pünktlich vor der Tür, K ist nicht da und hat auch nicht abgesagt. Beim Zurücktragen in den Lkw entsteht noch am selben Vormittag durch eine kleine Unachtsamkeit eines Monteurs ein Kratzer im Holzrahmen. M lagert das Sofa anschließend für zwei Wochen bei einer Spedition ein (Kosten 80 €), bis K einen neuen Termin vereinbart.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K muss die 80 € nicht zahlen, weil Lagerkosten zum allgemeinen Geschäftsrisiko eines Möbelhauses gehören.", "Falsch. § 304 weist Mehraufwendungen für die Aufbewahrung während des Annahmeverzugs ausdrücklich dem Gläubiger zu."], ["K kann wegen des Kratzers Nacherfüllung verlangen, weil M für jede Fahrlässigkeit seiner Monteure einstehen muss (§§ 276, 278).", "Falsch. Während des Annahmeverzugs haftet M nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I) – das gilt auch für die Gehilfen."], ["K muss die 80 € zahlen und kann wegen des Kratzers mindern, weil die Haftungserleichterung nur für Untergang, nicht für Beschädigung gilt.", "Falsch. § 300 I mildert die Haftung für jede Leistungsstörung am Leistungsgegenstand, auch für Beschädigungen."], ["K muss die 80 € nicht zahlen, weil sie nicht in Schuldnerverzug war und Schadensersatz ein Vertretenmüssen voraussetzt (§ 286 IV).", "Falsch. Es geht nicht um Schadensersatz wegen Schuldnerverzugs. § 304 ist ein verschuldensunabhängiger Aufwendungsersatzanspruch."], ["K muss die 80 € nur zahlen, wenn M ihr vorher eine Frist zur Abholung gesetzt hat (§ 323).", "Falsch. § 304 setzt nur Annahmeverzug und tatsächliche Mehraufwendungen voraus, keine Fristsetzung."], ["K muss die 80 € ersetzen und hat wegen des leicht fahrlässig verursachten Kratzers keine Rechte (§§ 300 I, 304).", "Richtig. Annahmeverzug durch tatsächliches Angebot (§ 294): Mehraufwendungen trägt K (§ 304); M haftet nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I)."]], "id": "P5-10", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Die Wäscherei W GmbH kauft beim Fachhändler F eine gewerbliche Waschmaschine für 9.000 €. Nach zwei Monaten fällt die Laugenpumpe aus, ein typischer Fertigungsfehler. Die Reparatur kostet 180 € und ist in einem Tag erledigt; eine Neulieferung würde F (nach Abzug des Restwerts der alten Maschine) rund 4.000 € kosten. W besteht auf einer neuen Maschine, weil man „einem reparierten Gerät nicht traut“. F bietet nur die Reparatur an.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["W kann eine neue Maschine verlangen, weil der Käufer zwischen Nachbesserung und Neulieferung frei wählt und der Verkäufer daran gebunden ist (§ 439 I).", "Falsch. Das Wahlrecht des Käufers besteht, findet aber seine Grenze in § 439 IV: Der Verkäufer kann die gewählte Art bei unverhältnismäßigen Kosten verweigern."], ["F darf die Neulieferung als unverhältnismäßig verweigern und W auf die Reparatur verweisen (§ 439 IV).", "Richtig. 4.000 € statt 180 € für einen gleichwertig behebbaren Mangel sind unverhältnismäßig; der Anspruch beschränkt sich auf die Reparatur (§ 439 IV 3)."], ["W kann sofort zurücktreten, weil ein Fertigungsfehler nach zwei Monaten die Nacherfüllung unzumutbar macht (§ 440).", "Falsch. Unzumutbar ist die Nacherfüllung nur bei besonderen Umständen (z. B. wiederholte Fehlschläge). Ein einfacher, schnell behebbarer Defekt genügt nicht."], ["F darf die Neulieferung nur verweigern, wenn W Verbraucherin wäre; gegenüber Unternehmern gilt § 439 IV nicht.", "Falsch. § 439 IV gilt für jeden Kaufvertrag, also auch zwischen Unternehmern."], ["W kann eine neue Maschine verlangen, muss aber die Differenz von 3.820 € selbst tragen (§ 439 II).", "Falsch. Eine solche Kostenteilung sieht das Gesetz nicht vor. Die Kosten der Nacherfüllung trägt der Verkäufer; er kann aber die unverhältnismäßige Art verweigern."], ["F darf beide Arten der Nacherfüllung verweigern, weil W als Unternehmerin den Mangel nicht unverzüglich gerügt hat (§ 377 HGB).", "Falsch. Laut Sachverhalt geht es um einen versteckten Mangel, der erst nach zwei Monaten auftrat; für ihn läuft die Rügefrist erst ab Entdeckung (§ 377 III HGB). Eine verspätete Rüge ist nicht ersichtlich."]], "id": "P5-11", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Fliesenleger L kauft für einen Kundenauftrag beim Baustoffhändler B 80 m² Bodenfliesen und verlegt sie fachgerecht im Bad des Kunden. Erst danach zeigen sich Haarrisse in der Glasur, die auf einen Brennfehler zurückgehen und vorher nicht erkennbar waren. Das Herausreißen und Neuverlegen kostet 3.200 €. B liefert neue Fliesen, will aber für Aus- und Einbau nicht aufkommen: „Sie sind Unternehmer, das ist Ihr Risiko.“", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["L bekommt die Aus- und Einbaukosten nicht ersetzt, weil ihre Erstattung nur beim Verbrauchsgüterkauf vorgesehen ist (§§ 474, 475).", "Falsch. § 439 III steht im allgemeinen Kaufrecht und gilt für alle Käufer, auch für Unternehmer."], ["L bekommt die Kosten nur ersetzt, wenn B den Brennfehler zu vertreten hat (§§ 280 I, 281).", "Falsch. Der Anspruch aus § 439 III ist Teil der Nacherfüllung und deshalb verschuldensunabhängig."], ["L kann nur verlangen, dass B die Fliesen selbst ausbaut und neu verlegt; Geld kann er nicht verlangen (§ 439 III).", "Falsch. § 439 III gibt einen Anspruch auf Ersatz der erforderlichen Aufwendungen. Ein Recht des Verkäufers, Aus- und Einbau selbst vorzunehmen, sieht die Vorschrift nicht vor."], ["L kann neben den neuen Fliesen Ersatz der erforderlichen Kosten für Ausbau und Neuverlegung verlangen, auch als Unternehmer (§ 439 III).", "Richtig. L hat die Fliesen ihrer Art entsprechend eingebaut, bevor der Mangel offenbar wurde. Dann schuldet B im Rahmen der Nacherfüllung die erforderlichen Aufwendungen."], ["L kann die Kosten nicht verlangen, weil er die Fliesen vor dem Einbau auf Mängel hätte untersuchen müssen (§ 442).", "Falsch. § 442 schließt Rechte nur bei Kenntnis oder grob fahrlässiger Unkenntnis aus. Die Risse waren vor dem Einbau nicht erkennbar."], ["L bekommt die Kosten nur, wenn der Kunde zuvor von ihm Nacherfüllung verlangt hat (§ 634).", "Falsch. Das Verhältnis zum Kunden ist für den Anspruch gegen B unerheblich. Maßgeblich ist allein der Kaufvertrag zwischen L und B."]], "id": "P5-12", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Studentin S kauft am 10. Januar beim Elektronikmarkt E einen neuen Fernseher. Am 2. November desselben Jahres fällt die Hintergrundbeleuchtung aus. E meint, S müsse beweisen, dass der Fehler schon beim Kauf angelegt war; außerdem sei die Frist für die Beweislastumkehr nach sechs Monaten abgelaufen. Ob der Defekt auf einen Herstellungsfehler oder einen Bedienfehler zurückgeht, lässt sich nicht aufklären.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Es wird vermutet, dass der Fernseher schon bei Übergabe mangelhaft war, weil sich der Defekt innerhalb eines Jahres zeigte (§ 477 I).", "Richtig. Seit 2022 gilt die Vermutung beim Verbrauchsgüterkauf ein Jahr lang. Will E sich entlasten, muss er beweisen, dass der Fernseher bei Übergabe mangelfrei war."], ["S muss beweisen, dass der Fehler bei Übergabe vorlag, weil die Vermutung nur sechs Monate gilt (§ 477 a. F.).", "Falsch. Sechs Monate galten bis Ende 2021. Für Verträge ab 1.1.2022 beträgt die Frist ein Jahr."], ["Es wird vermutet, dass ein Mangel vorlag, aber nur, wenn S den Fernseher innerhalb der ersten sechs Monate mindestens einmal reklamiert hat.", "Falsch. Eine vorherige Reklamation ist keine Voraussetzung. Es genügt, dass sich der mangelhafte Zustand innerhalb eines Jahres zeigt."], ["S hat keine Rechte, weil Mängelrechte bei Elektronik nach zehn Monaten verjährt sind (§ 438 I Nr. 3).", "Falsch. Die Verjährungsfrist beträgt zwei Jahre ab Ablieferung (§ 438 I Nr. 3, II). Sie ist noch nicht abgelaufen."], ["Die Vermutung gilt, aber nur gegenüber dem Hersteller, nicht gegenüber dem Händler E (§ 477).", "Falsch. Die Vermutung wirkt im Verhältnis Käufer – Verkäufer. Der Hersteller ist gar nicht Vertragspartner der S."], ["Es wird vermutet, dass der Fehler bei Übergabe vorlag; E kann diese Vermutung aber nicht widerlegen, sie ist unwiderleglich.", "Falsch. Die Vermutung ist widerleglich. E kann den Gegenbeweis führen, z. B. dass ein Bedienfehler vorliegt."]], "id": "P5-13", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "K kauft beim Autohaus A einen Neuwagen für 32.000 €. Bei Übergabe zeigt sich, dass die Halterung der Mittelarmlehne leicht klappert. Die Beseitigung würde 120 € kosten. A lehnt jede Nachbesserung ab, weil das „Kinkerlitzchen“ seien. K setzt eine angemessene Frist, die ungenutzt verstreicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K kann zurücktreten, weil A die Nacherfüllung ernsthaft verweigert hat und eine Frist deshalb ohnehin entbehrlich war (§ 323 II Nr. 1).", "Falsch. Die Verweigerung macht nur die Frist entbehrlich. Der Rücktritt scheitert aber an der Unerheblichkeit des Mangels (§ 323 V 2)."], ["K kann weder zurücktreten noch mindern, weil ein Mangel von 120 € bei einem Neuwagen rechtlich gar kein Mangel ist (§ 434).", "Falsch. Auch geringfügige Abweichungen sind Sachmängel. Die Bagatelle schließt nur den Rücktritt aus."], ["K kann zurücktreten, weil bei Neuwagen jeder Mangel erheblich ist, solange er nicht behoben wurde.", "Falsch. Bei behebbaren Mängeln ist die Erheblichkeit nach dem BGH in der Regel erst ab etwa 5 % des Kaufpreises an Beseitigungskosten anzunehmen. 120 € liegen weit darunter."], ["K kann mindern, aber nur, wenn er zuvor erfolglos den Rücktritt erklärt hat (§ 441 I 1).", "Falsch. Die Minderung erklärt der Käufer „statt zurückzutreten“. Ein vorheriger Rücktritt ist nicht nötig – er wäre hier ja auch unwirksam."], ["Rücktritt scheidet aus, Minderung nicht: Der Bagatellausschluss gilt nur für den Rücktritt (§§ 323 V 2, 441 I 2).", "Richtig. Der Rücktritt ist bei unerheblichem Mangel ausgeschlossen. § 441 I 2 erklärt diesen Ausschluss für die Minderung ausdrücklich für unanwendbar."], ["K kann nur Schadensersatz statt der ganzen Leistung verlangen, weil A die Reparatur verweigert hat (§ 281 I 3).", "Falsch. Schadensersatz statt der ganzen Leistung ist bei unerheblicher Pflichtverletzung gerade ausgeschlossen (§ 281 I 3)."]], "id": "P5-14", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Privatmann V verkauft dem Privatmann K seinen 9 Jahre alten Kombi für 7.500 €. Im Vertrag steht: „Gekauft wie gesehen, unter Ausschluss jeder Gewährleistung.“ V weiß, dass sich unter der neuen Fußmatte ein großflächiges, frisch überlackiertes Durchrostungsloch im Bodenblech befindet, und sagt nichts. K entdeckt das Loch zweieinhalb Jahre nach der Übergabe bei einer Reparatur und verlangt Minderung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K hat keine Rechte, weil zwischen Privatleuten ein Gewährleistungsausschluss uneingeschränkt wirksam ist (§ 476 gilt nicht).", "Falsch. Unter Privaten gilt § 476 zwar nicht, wohl aber § 444: Bei arglistigem Verschweigen kann sich der Verkäufer nicht auf den Ausschluss berufen."], ["K hat keine Rechte, weil Mängelansprüche bei beweglichen Sachen zwei Jahre nach Ablieferung verjähren, unabhängig von der Kenntnis des Käufers (§ 438 I Nr. 3).", "Falsch. Bei Arglist gilt statt der zwei Jahre die regelmäßige Verjährung (§ 438 III 1): drei Jahre ab Ende des Jahres der Kenntnis (§§ 195, 199)."], ["K kann mindern; V kann sich wegen Arglist weder auf den Ausschluss noch auf die zweijährige Verjährung berufen (§§ 444, 438 III).", "Richtig. Arglistiges Verschweigen sperrt den Haftungsausschluss (§ 444). Die Verjährung richtet sich nach der Regelfrist, die ab Kenntnis zu laufen beginnt."], ["K kann nur anfechten, weil bei Arglist die Mängelrechte durch § 123 verdrängt werden.", "Falsch. Anfechtung (§ 123) und Mängelrechte stehen nebeneinander; K kann wählen. Wer anficht, verliert allerdings die Mängelrechte, weil der Vertrag wegfällt."], ["K kann mindern, aber nur, wenn er V innerhalb eines Monats nach Entdeckung eine Frist zur Nachbesserung gesetzt hat (§ 323 I).", "Falsch. Eine solche Monatsfrist gibt es nicht. Unter Umständen ist die Fristsetzung bei Arglist sogar entbehrlich, weil die Vertrauensgrundlage zerstört ist."], ["K kann mindern, weil der Ausschluss „gekauft wie gesehen“ nur sichtbare Mängel erfasst und versteckte Mängel nie ausschließt.", "Falsch. Ein umfassender Gewährleistungsausschluss erfasst grundsätzlich auch versteckte Mängel. Unwirksam ist er hier nur wegen der Arglist (§ 444)."]], "id": "P5-15", "tag": "Neu · Transfer", "neu": true}, {"topic": "kauf", "sv": "Café-Betreiberin C bestellt beim Gastrohändler G eine Siebträgermaschine „Modell Duo 2-gruppig“. G liefert versehentlich das kleinere „Modell Solo 1-gruppig“, das 600 € billiger ist. C bemerkt das beim Auspacken und verlangt die richtige Maschine. G meint, er habe „ja geliefert“, C könne höchstens den Differenzbetrag zurückverlangen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["C kann nur die 600 € Preisdifferenz verlangen, weil G den Vertrag mit der Lieferung einer Maschine erfüllt hat (§ 362 I).", "Falsch. Erfüllung tritt nur mit der geschuldeten Leistung ein. Ein anderes Modell erfüllt nicht, es wird wie ein Sachmangel behandelt."], ["C kann Lieferung der richtigen Maschine verlangen; ein aliud steht einem Sachmangel gleich (§§ 434 V, 439 I).", "Richtig. Die Falschlieferung (aliud) steht einem Sachmangel gleich. C hat die Rechte aus § 437, zuerst Nacherfüllung durch Lieferung der geschuldeten Maschine."], ["C kann den Vertrag sofort anfechten, weil G sich bei der Lieferung geirrt hat (§ 119 I).", "Falsch. Ein Irrtum bei der Lieferung betrifft keine Willenserklärung beim Vertragsschluss. Der Vertrag ist so geschlossen, wie beide wollten."], ["C kann sofort zurücktreten, weil eine Falschlieferung keine Nacherfüllung zulässt (§ 326 V).", "Falsch. Die richtige Maschine kann ohne Weiteres geliefert werden; § 326 V setzt Unmöglichkeit voraus. Es bleibt beim Vorrang der Nacherfüllung."], ["C hat keine Mängelrechte, weil eine Falschlieferung kein Mangel der gelieferten Sache ist; sie kann nur aus § 433 I auf Erfüllung klagen, ohne die kurzen Mängelfristen.", "Falsch. Seit der Schuldrechtsreform stellt § 434 V die Falschlieferung dem Sachmangel gleich. Es gelten die Mängelrechte und deren Verjährung (§ 438)."], ["C muss das kleinere Modell behalten, wenn sie nicht innerhalb von 14 Tagen widerruft (§§ 312g, 355).", "Falsch. C ist Unternehmerin; ein Widerrufsrecht hat sie nicht. Außerdem geht es nicht um Reue, sondern um eine Falschlieferung."]], "id": "P5-16", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Hobbyfotografin H veröffentlicht auf ihrem Instagram-Account ein stimmungsvolles Foto der Münchner Altstadt. Café-Betreiber C lädt das Bild ohne Nachfrage herunter und druckt es auf 5.000 Werbeflyer. Für eine solche Nutzung wäre eine Lizenzgebühr von 300 € üblich. C meint, H habe keinen Schaden, sie hätte das Foto ohnehin nie verkauft; außerdem habe er mit den Flyern kaum Umsatz gemacht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["H kann nichts verlangen, weil ihr kein Vermögensschaden entstanden ist und sie das Bild nie lizenziert hätte.", "Falsch. Die Eingriffskondiktion fragt nicht nach dem Schaden der H, sondern nach dem Vorteil des C. Ob H selbst lizenziert hätte, ist unerheblich."], ["H kann den gesamten durch die Flyer erzielten Café-Gewinn herausverlangen (§ 818 I).", "Falsch. Erlangt hat C den Gebrauch des Fotos, nicht den Café-Gewinn. Dieser beruht auf seiner eigenen Leistung. Geschuldet ist der Wert des Gebrauchs."], ["H kann 300 € aus Leistungskondiktion verlangen, weil das Foto öffentlich zugänglich und damit an C geleistet war (§ 812 I 1 Alt. 1).", "Falsch. Das Einstellen ins Netz ist keine bewusste, zweckgerichtete Zuwendung an C. Es geht um einen Eingriff, nicht um eine Leistung."], ["H kann von C 300 € Wertersatz für die Nutzung verlangen (§§ 812 I 1 Alt. 2, 818 II).", "Richtig. C hat die Nutzung eines H zugewiesenen Rechts ohne Rechtsgrund erlangt. Weil er sie nicht herausgeben kann, schuldet er Wertersatz in Höhe der üblichen Lizenzgebühr."], ["H kann nichts verlangen, weil C entreichert ist, da die Flyer kaum Umsatz gebracht haben (§ 818 III).", "Falsch. Die Ersparnis der Lizenzgebühr bleibt in C's Vermögen, gleich ob sich die Werbung gelohnt hat. Eine Entreicherung liegt darin nicht."], ["H kann nur Unterlassung verlangen; Geld gibt es erst, wenn C nach einer Abmahnung weiter Flyer verteilt (§ 1004).", "Falsch. Unterlassung kann H zusätzlich verlangen. Der Wertersatz für die schon erfolgte Nutzung hängt aber nicht von einer vorherigen Abmahnung ab."]], "id": "P5-17", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Studentin S sieht vom Fenster aus, wie ein Unbekannter das Schloss ihres Fahrrads knackt und davonfährt. Sie rennt sofort hinterher, holt ihn an der nächsten Ampel ein, zieht ihn am Arm vom Rad und nimmt es wieder mit. Der Mann trägt eine Prellung davon und droht mit einer Anzeige; S habe „Selbstjustiz“ geübt und hätte die Polizei rufen müssen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["S durfte das Rad nicht selbst zurückholen, weil Selbsthilfe nur zulässig ist, wenn obrigkeitliche Hilfe nicht rechtzeitig zu erlangen ist (§ 229).", "Falsch. § 229 betrifft die allgemeine Selbsthilfe zur Sicherung von Ansprüchen. Für den Besitzer gibt § 859 II ein eigenes, weitergehendes Recht gegenüber dem auf frischer Tat verfolgten Täter."], ["S durfte das Rad nur zurückholen, wenn sie beweisen kann, dass sie Eigentümerin ist (§ 1006).", "Falsch. Der Besitzschutz knüpft an den Besitz an, nicht an das Eigentum. S war unmittelbare Besitzerin."], ["S durfte das Rad zurückholen, muss dem Mann aber Schadensersatz für die Prellung leisten, weil Gewalt nie erlaubt ist (§ 823 I).", "Falsch. § 859 II erlaubt ausdrücklich Gewalt. Die Körperverletzung ist dadurch gerechtfertigt, soweit S – wie hier – nicht über das Erforderliche hinausging."], ["S durfte das Rad nicht zurückholen, weil der Dieb mit dem Wegfahren selbst Besitz erlangt hat und dieser Besitz geschützt ist (§ 861).", "Falsch. Der durch verbotene Eigenmacht erlangte Besitz ist fehlerhaft (§ 858 II). Gegenüber S kann sich der Dieb nicht auf Besitzschutz berufen."], ["S durfte das Rad zurückholen, aber nur ohne Gewalt; das Herunterziehen vom Rad war rechtswidrig (§ 859 I).", "Falsch. § 859 II erlaubt dem Besitzer ausdrücklich, die Sache dem verfolgten Täter mit Gewalt wieder abzunehmen."], ["S durfte dem auf frischer Tat verfolgten Dieb das Rad mit Gewalt wieder abnehmen (§ 859 II).", "Richtig. Der Dieb hat S den Besitz durch verbotene Eigenmacht entzogen (§ 858 I). Bei Verfolgung auf frischer Tat darf der Besitzer sich die Sache mit Gewalt zurückholen."]], "id": "P5-18", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Rentner R hat an seinem Briefkasten einen gut lesbaren Aufkleber angebracht: „Bitte keine Werbung einwerfen!“ Der Lieferdienst P GmbH lässt trotzdem jede Woche Prospekte einwerfen. R hat das zweimal schriftlich beanstandet, ohne Ergebnis. P meint, es handle sich um eine Bagatelle, R könne die Prospekte ja wegwerfen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["R kann Unterlassung verlangen, weil der Einwurf gegen seinen erklärten Willen Eigentum und Besitz stört (§§ 1004 I, 862 I).", "Richtig. Der BGH sieht im Einwurf trotz Sperrvermerk eine Eigentums- und Besitzstörung. Wiederholungsgefahr besteht, R kann Unterlassung verlangen."], ["R kann nichts verlangen, weil das Einwerfen von Werbung sozialadäquat ist und von jedem Briefkasteninhaber geduldet werden muss (§ 1004 II).", "Falsch. Eine Duldungspflicht besteht nicht, wenn der Inhaber ausdrücklich widersprochen hat. Gerade der Aufkleber beseitigt die Sozialadäquanz."], ["R kann nur Schadensersatz für die Entsorgungskosten verlangen, aber keine Unterlassung (§ 823 I).", "Falsch. Unterlassung ist gerade der passende Anspruch gegen fortdauernde Störungen. Ein Schaden ist dafür nicht erforderlich."], ["R kann Unterlassung nur verlangen, wenn er nachweist, dass ihm durch die Prospekte ein Schaden entstanden ist (§ 1004 I).", "Falsch. § 1004 I setzt keinen Schaden und kein Verschulden voraus, sondern nur eine rechtswidrige Beeinträchtigung."], ["R kann nichts verlangen, weil nicht P selbst, sondern die angestellten Austräger die Prospekte einwerfen (§ 831).", "Falsch. Störer ist auch, wer die Beeinträchtigung veranlasst. P lässt die Prospekte verteilen und ist deshalb selbst zur Unterlassung verpflichtet."], ["R kann Unterlassung verlangen, aber erst, wenn er P zuvor eine Vertragsstrafe angedroht hat (§ 339).", "Falsch. Eine Vertragsstrafe setzt eine Vereinbarung voraus und ist keine Voraussetzung des Unterlassungsanspruchs."]], "id": "P5-19", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Dieb D entwendet der Rentnerin R aus der Handtasche einen 100-€-Schein. Eine Stunde später bezahlt er damit beim Bäcker B einen Kuchen für 30 € und erhält 70 € Wechselgeld. B ahnt nichts. R hat sich die Seriennummer des Scheins notiert, weil sie ihn kurz zuvor bei der Bank abgehoben hat, und findet ihn am Abend in B's Kasse wieder.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["R ist Eigentümerin des Scheins geblieben, weil gestohlene Sachen nicht gutgläubig erworben werden können (§ 935 I).", "Falsch. § 935 II macht für Geld eine ausdrückliche Ausnahme: Es kann auch dann gutgläubig erworben werden, wenn es abhandengekommen ist."], ["B ist Eigentümer geworden, R kann den Schein aber nach § 985 herausverlangen, weil sie die Seriennummer kennt.", "Falsch. § 985 setzt Eigentum der R voraus. Das hat sie durch den gutgläubigen Erwerb des B verloren; die Seriennummer ändert daran nichts."], ["B ist nur Besitzer geworden, weil Geld nach § 935 II nur bei öffentlicher Versteigerung gutgläubig erworben werden kann.", "Falsch. § 935 II nennt drei Fälle nebeneinander: Geld, Inhaberpapiere und Sachen aus öffentlicher Versteigerung. Für Geld ist keine Versteigerung nötig."], ["B ist Eigentümer geworden, muss den Schein aber an R zurückgeben, weil er ihn unentgeltlich erlangt hat (§ 816 I 2).", "Falsch. B hat entgeltlich erworben – er hat den Kuchen und 70 € Wechselgeld gegeben. § 816 I 2 greift nur bei unentgeltlichem Erwerb."], ["B hat gutgläubig Eigentum am Schein erworben, obwohl er gestohlen war (§§ 929 S. 1, 932 I, 935 II).", "Richtig. Einigung und Übergabe liegen vor, B war gutgläubig. Die Sperre des § 935 I gilt für Geld nicht. R muss sich an D halten."], ["R und B sind Miteigentümer, weil der Schein mit dem übrigen Kassenbestand vermischt wurde (§§ 948, 947).", "Falsch. Auf eine Vermischung kommt es nicht an, weil B schon durch gutgläubigen Erwerb Alleineigentümer wurde. Außerdem ist der Schein dank Seriennummer unterscheidbar."]], "id": "P5-20", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Dieb D stiehlt aus dem Lager des Holzhändlers E Eichenbohlen im Wert von 400 € und verkauft sie an den ahnungslosen Schreiner S für 300 €. S fertigt daraus in 40 Arbeitsstunden einen Esstisch im Wert von 4.500 €. E entdeckt die markierten Bohlen am Tisch und verlangt den Tisch heraus.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["E ist Eigentümer des Tisches, weil an gestohlenen Sachen kein Eigentum erworben werden kann (§ 935 I).", "Falsch. § 935 I sperrt nur den rechtsgeschäftlichen gutgläubigen Erwerb. Die Verarbeitung (§ 950) ist ein gesetzlicher Erwerb, für den § 935 nicht gilt."], ["S ist durch Verarbeitung Eigentümer geworden; E kann von S Wertersatz in Geld für die Bohlen verlangen (§§ 950 I, 951 I).", "Richtig. Der Wert der Verarbeitung übersteigt den Stoffwert deutlich, S wird Eigentümer. E verliert sein Eigentum und hat einen Geldanspruch nach §§ 951 I, 812."], ["S ist Eigentümer geworden, weil er die Bohlen gutgläubig gekauft hat (§§ 929, 932).", "Falsch. Ergebnis richtig, Begründung falsch: Der gutgläubige Erwerb der Bohlen scheiterte an § 935 I. S wird erst durch die Verarbeitung Eigentümer."], ["E und S sind Miteigentümer am Tisch im Verhältnis 400 : 4.100 (§ 947 I).", "Falsch. § 947 betrifft die Verbindung mehrerer beweglicher Sachen. Bei der Verarbeitung zu einer neuen Sache gilt § 950 – Alleineigentum des Herstellers."], ["S ist Eigentümer geworden; E kann aber nichts verlangen, weil S die Bohlen schon an D bezahlt hat (§ 818 III).", "Falsch. Der an den Dieb gezahlte Kaufpreis mindert den Anspruch nach der Rechtsprechung nicht. Sonst trüge der Eigentümer das Risiko des Diebstahls doppelt."], ["E ist Eigentümer geblieben und kann den Tisch herausverlangen, muss S aber den Arbeitslohn ersetzen (§§ 985, 994).", "Falsch. E ist nicht mehr Eigentümer, weil § 950 kraft Gesetzes S zum Eigentümer gemacht hat. Ein Anspruch aus § 985 scheidet aus."]], "id": "P5-21", "tag": "Neu · Transfer", "neu": true}, {"topic": "sach", "sv": "Die Zulieferer Z GmbH liefert der Automobil A AG Bauteile für 80.000 €. Die Einkaufsbedingungen der A enthalten den Satz: „Forderungen gegen uns dürfen nicht abgetreten werden.“ Z tritt die Forderung trotzdem zur Finanzierung an die Bank B ab und zeigt dies A an. A zahlt dennoch an Z, die das Geld nicht weiterleitet. B verlangt von A Zahlung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Die Abtretung ist wegen des vereinbarten Abtretungsverbots unwirksam; A schuldet B nichts (§ 399).", "Falsch. Für beidseitige Handelsgeschäfte unter Kaufleuten überlagert § 354a I 1 HGB die Regel des § 399: Die Abtretung ist trotzdem wirksam."], ["Die Abtretung ist wirksam; A muss an B noch einmal zahlen, weil A von der Abtretung wusste (§ 407 I).", "Falsch. § 354a I 2 HGB erlaubt dem Schuldner, trotz Kenntnis mit befreiender Wirkung an den bisherigen Gläubiger zu leisten."], ["Die Abtretung ist wirksam; A konnte aber trotzdem mit befreiender Wirkung an Z zahlen (§ 354a I HGB).", "Richtig. Bei beidseitigen Handelsgeschäften ist die Abtretung trotz Verbots wirksam, der Schuldner darf aber weiterhin an den alten Gläubiger zahlen. B muss sich an Z halten."], ["Die Abtretung ist wirksam, weil Abtretungsverbote in AGB stets unwirksam sind (§ 307).", "Falsch. Abtretungsverbote in AGB sind nicht generell unwirksam. Der Grund für die Wirksamkeit der Abtretung liegt hier in § 354a HGB."], ["Die Abtretung ist schwebend unwirksam, bis A zustimmt; mit der Zahlung an Z hat A die Zustimmung verweigert (§§ 182, 184).", "Falsch. Eine Zustimmung des Schuldners ist für die Wirksamkeit der Abtretung nicht erforderlich. § 354a HGB macht sie unabhängig vom Verbot wirksam."], ["Die Abtretung ist wirksam; A muss an B zahlen und kann von Z das Geld nach § 812 zurückverlangen.", "Falsch. A ist durch die Zahlung an Z frei geworden (§ 354a I 2 HGB). Ausgleichen müssen sich B und Z untereinander (§ 816 II)."]], "id": "P5-22", "tag": "Neu · Transfer", "neu": true}, {"topic": "del", "sv": "Die gut erzogene Familienhündin „Bella“ der Lehrerin L hat noch nie jemanden gebissen. Beim Spaziergang an der kurzen Leine erschrickt sie über einen platzenden Luftballon und schnappt nach der Hand der Passantin P. P muss genäht werden und verlangt Schmerzensgeld. L meint, sie habe alles richtig gemacht und hafte deshalb nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["L haftet nicht, weil sie den Hund ordnungsgemäß an der kurzen Leine geführt und damit ihre Aufsichtspflicht erfüllt hat (§ 833 S. 2).", "Falsch. Die Entlastung nach § 833 S. 2 gilt nur für Nutztiere, die dem Beruf oder Erwerb des Halters dienen. Bella ist ein privater Familienhund."], ["L haftet nur, wenn sie fahrlässig gehandelt hat; da Bella noch nie gebissen hat, fehlt es daran (§ 823 I).", "Falsch. Neben § 823 I gibt es § 833 S. 1 – eine Gefährdungshaftung ohne Verschulden. Auf Vorhersehbarkeit kommt es dort nicht an."], ["L haftet nicht, weil sich keine typische Tiergefahr verwirklicht hat, sondern ein äußeres Ereignis (Luftballon).", "Falsch. Das unberechenbare Schnappen aus Schreck ist gerade typisches tierisches Verhalten. Dass es durch einen äußeren Reiz ausgelöst wurde, ändert daran nichts."], ["L haftet als Tierhalterin ohne Verschulden auf Schadensersatz einschließlich Schmerzensgeld (§§ 833 S. 1, 253 II).", "Richtig. Bei Luxustieren haftet der Halter für die Tiergefahr verschuldensunabhängig. Für Körperverletzungen umfasst der Ersatz auch ein Schmerzensgeld."], ["L haftet, aber nur auf Ersatz der Heilungskosten; Schmerzensgeld gibt es bei Gefährdungshaftung nicht (§ 253 I).", "Falsch. § 253 II gewährt bei Verletzung von Körper oder Gesundheit Schmerzensgeld unabhängig vom Haftungsgrund, also auch bei Gefährdungshaftung."], ["Nicht L, sondern nur ihre Haftpflichtversicherung haftet gegenüber P, weil Hundehalter versichert sein müssen.", "Falsch. Haftpflichtig ist L als Halterin. Ob und wie eine Versicherung zahlt, betrifft nur das Innenverhältnis zu ihrer Versicherung."]], "id": "P5-23", "tag": "Neu · Transfer", "neu": true}, {"topic": "del", "sv": "Anlageberater A, der nicht für eine Bank tätig ist, sondern auf eigene Rechnung Kontakte vermittelt, überredet die Lehrerin L, 20.000 € in eine angebliche Solarfirma zu investieren. Er weiß, dass die Firma nur auf dem Papier existiert, und kassiert eine Provision. Das Geld ist weg. Mit L hat A keinen Vertrag geschlossen; sie hat direkt an die Scheinfirma überwiesen. L verlangt von A Ersatz.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["L kann von A 20.000 € verlangen, weil A durch Betrug ein Schutzgesetz verletzt hat (§ 823 II i. V. m. § 263 StGB).", "Richtig. § 263 StGB schützt das Vermögen des Einzelnen und ist Schutzgesetz. Über § 823 II ist deshalb auch der reine Vermögensschaden ersatzfähig (daneben § 826)."], ["L kann nichts verlangen, weil das Vermögen kein von § 823 I geschütztes Rechtsgut ist und kein Vertrag mit A besteht.", "Falsch. § 823 I schützt das Vermögen tatsächlich nicht. § 823 II schließt diese Lücke aber bei Verletzung eines Schutzgesetzes, das gerade das Vermögen schützt."], ["L kann von A 20.000 € aus § 823 I verlangen, weil das Geld ihr Eigentum war und durch A beschädigt wurde.", "Falsch. Bei einer Überweisung geht es um Buchgeld, also nicht um Eigentum an einer Sache. Verletzt ist nur das Vermögen."], ["L kann von A nur die Provision herausverlangen, weil A nur insoweit bereichert ist (§ 812 I).", "Falsch. Die Provision zahlte die Scheinfirma, nicht L; zwischen L und A besteht keine Leistungsbeziehung. Der volle Schaden ist über § 823 II, § 826 ersetzbar."], ["L kann nichts verlangen, weil sie freiwillig überwiesen hat und deshalb ihr Mitverschulden den Anspruch ganz ausschließt (§ 254).", "Falsch. Wer vorsätzlich täuscht, kann dem Opfer regelmäßig kein Mitverschulden wegen Leichtgläubigkeit entgegenhalten. Ein völliger Ausschluss scheidet jedenfalls aus."], ["L kann von A 20.000 € nur verlangen, wenn A zuvor strafrechtlich verurteilt wurde (§ 823 II).", "Falsch. Das Zivilgericht prüft den Schutzgesetzverstoß selbst. Eine vorherige Verurteilung ist nicht erforderlich."]], "id": "P5-24", "tag": "Neu · Transfer", "neu": true}, {"topic": "del", "sv": "Kundin K lässt sich beim Friseursalon F die Haare blondieren. Die Auszubildende lässt das Mittel aus Unachtsamkeit 20 Minuten zu lange einwirken. K erleidet schmerzhafte Verätzungen der Kopfhaut, die wochenlang behandelt werden müssen. K verklagt nur den Inhaber F – und zwar ausschließlich aus dem Vertrag – auf Schmerzensgeld. F meint, Schmerzensgeld gebe es nur aus Delikt, und für die Azubi könne er sich entlasten, weil er sie sorgfältig ausgewählt habe.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K hat keinen Anspruch, weil Schmerzensgeld nur bei unerlaubten Handlungen gewährt wird (§§ 823, 847 a. F.).", "Falsch. § 847 a. F. ist seit 2002 aufgehoben. Heute gilt § 253 II für alle Anspruchsgrundlagen, also auch für vertragliche."], ["K hat einen Anspruch, aber nur auf Ersatz der Behandlungskosten; Schmerzensgeld setzt Vorsatz voraus (§ 253 II).", "Falsch. § 253 II verlangt keinen Vorsatz. Es genügt, dass wegen einer Verletzung von Körper oder Gesundheit Schadensersatz zu leisten ist."], ["K hat keinen vertraglichen Anspruch, weil F sich für die sorgfältig ausgewählte Azubi entlasten kann (§ 831 I 2).", "Falsch. Die Entlastung nach § 831 I 2 gibt es nur im Deliktsrecht. Im Vertrag haftet F für seine Erfüllungsgehilfen ohne Entlastungsmöglichkeit (§ 278)."], ["K hat einen vertraglichen Anspruch nur gegen die Azubi selbst, weil sie den Fehler gemacht hat (§ 280 I).", "Falsch. Vertragspartner ist F, nicht die Azubi. F muss sich deren Verschulden nach § 278 zurechnen lassen."], ["K hat einen Anspruch auf Schmerzensgeld, aber nur, wenn die Verletzung zu bleibenden Schäden geführt hat oder grob fahrlässig verursacht wurde (§ 253 II).", "Falsch. Auch vorübergehende Verletzungen begründen Schmerzensgeld. Die Dauer wirkt sich nur auf die Höhe aus."], ["K kann aus dem Vertrag Schmerzensgeld verlangen; F haftet für die Azubi (§§ 280 I, 278, 253 II).", "Richtig. Pflichtverletzung aus dem Dienst-/Werkvertrag, Verschulden der Erfüllungsgehilfin wird F zugerechnet, und § 253 II gilt auch für vertragliche Ansprüche."]], "id": "P5-25", "tag": "Neu · Transfer", "neu": true}, {"topic": "del", "sv": "Die Nachbarsjungen A (19) und B (20) spielen im Hof Fußball. Beide schießen abwechselnd mit voller Wucht gegen das Garagentor des Eigentümers E, obwohl das Tor schon Dellen hat. Am Ende ist das Tor so verbeult, dass es ersetzt werden muss (2.400 €). Welche Dellen von wem stammen, lässt sich nicht feststellen. E verlangt von A die vollen 2.400 €. A meint, er schulde allenfalls die Hälfte.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["A schuldet nur 1.200 €, weil mehrere Schädiger jeweils nur ihren Anteil zu tragen haben (§ 420).", "Falsch. § 420 (Teilschuld) gilt nur im Zweifel bei teilbaren Leistungen. Für mehrere aus Delikt Verantwortliche ordnet § 840 I Gesamtschuld an."], ["A schuldet nichts, weil nicht feststeht, dass gerade er den entscheidenden Schaden verursacht hat (§ 823 I).", "Falsch. Beide haben gemeinschaftlich gehandelt; zudem gilt § 830 I 2 für Fälle, in denen sich nicht ermitteln lässt, wer den Schaden verursacht hat."], ["E kann von A alles verlangen; A hat im Innenverhältnis Ausgleich gegen B (§§ 840 I, 421, 426).", "Richtig. Mehrere Verantwortliche haften als Gesamtschuldner. E darf von jedem das Ganze fordern; der Ausgleich erfolgt im Innenverhältnis, im Zweifel zu gleichen Teilen."], ["E muss A und B zusammen verklagen, weil Gesamtschuldner nur gemeinsam in Anspruch genommen werden können (§ 421).", "Falsch. Gerade das Gegenteil: Bei der Gesamtschuld kann der Gläubiger die Leistung nach Belieben von jedem Schuldner ganz oder teilweise fordern."], ["E kann von A die vollen 2.400 € verlangen; A hat aber keinen Rückgriff gegen B, weil er selbst mitgehandelt hat und sich deshalb nicht auf § 426 berufen kann.", "Falsch. § 426 I gibt dem zahlenden Gesamtschuldner einen Ausgleichsanspruch gegen den anderen, im Zweifel zu gleichen Teilen."], ["E kann von beiden jeweils 2.400 € verlangen, also insgesamt 4.800 € (§ 840 I).", "Falsch. Bei der Gesamtschuld kann der Gläubiger die Leistung nur einmal fordern (§ 421 S. 1). Zahlt einer, wirkt das für alle (§ 422)."]], "id": "P5-26", "tag": "Neu · Transfer", "neu": true}, {"topic": "per", "sv": "Die 15-jährige Mara nimmt an einem kostenlosen Gewinnspiel eines Radiosenders teil und gewinnt 3.000 €, die ihr der Sender bar auszahlt. Ihre Eltern wissen davon nichts. Mara kauft mit dem Geld beim Zweiradhändler Z einen gebrauchten Motorroller für 2.800 € und bezahlt sofort bar. Als die Eltern davon erfahren, verweigern sie gegenüber Z die Genehmigung. Z meint, der Kauf sei „mit eigenem Geld vollständig bezahlt“ und deshalb wirksam.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Der Rollerkauf ist wirksam, weil Mara mit ihrem eigenen Geld bezahlt hat und es auf die Herkunft nicht ankommt (§ 110).", "Falsch. § 110 verlangt Mittel, die der gesetzliche Vertreter oder ein Dritter mit dessen Zustimmung zu diesem Zweck oder zur freien Verfügung überlassen hat. Dass das Geld Mara gehört, genügt nicht."], ["Schon die Teilnahme am Gewinnspiel war unwirksam, weil Mara dafür die Zustimmung ihrer Eltern gebraucht hätte; deshalb gehört das Geld dem Sender.", "Falsch. Die kostenlose Teilnahme und die Annahme des Gewinns bringen Mara nur rechtliche Vorteile (§ 107). Sie ist Eigentümerin des Geldes geworden."], ["Der Rollerkauf ist wirksam, weil Mara sofort und vollständig bar bezahlt hat und Z deshalb auf die Wirksamkeit vertrauen durfte (§ 110).", "Falsch. Die vollständige Zahlung reicht nur, wenn sie mit überlassenen Mitteln erfolgt. Ein Gutglaubensschutz des Vertragspartners ist im Minderjährigenrecht nicht vorgesehen."], ["Der Rollerkauf ist wirksam, weil Mara mit 15 für Geschäfte bis zur Höhe ihres eigenen Vermögens voll geschäftsfähig ist (§ 106).", "Falsch. Eine solche Vermögensgrenze gibt es nicht. Mit 15 ist Mara beschränkt geschäftsfähig; nachteilige Geschäfte brauchen die Zustimmung der Eltern."], ["Der Rollerkauf ist unwirksam, weil der Gewinn nicht mit Zustimmung der Eltern zur freien Verfügung überlassen war (§§ 107, 108 I, 110).", "Richtig. Der Sender hat das Geld ohne Zustimmung der Eltern übergeben; § 110 greift deshalb nicht. Ohne Einwilligung war der Kauf schwebend unwirksam und ist nach der Verweigerung endgültig unwirksam."], ["Der Rollerkauf ist schwebend unwirksam und wird wirksam, sobald Mara volljährig ist, ohne dass es einer Erklärung bedarf (§ 108 III).", "Falsch. Mit der Verweigerung der Eltern ist der Vertrag schon endgültig unwirksam. Auch § 108 III verlangt im Übrigen eine Genehmigung des volljährig Gewordenen."]], "id": "P5-27", "tag": "Neu · Transfer", "neu": true}, {"topic": "per", "sv": "Großvater G schenkt seinem 16-jährigen Enkel E ein unvermietetes Einfamilienhaus. Das Grundstück ist mit einer Grundschuld über 50.000 € zugunsten einer Bank belastet, die einen Kredit des G sichert. G zahlt die Raten selbst weiter. Schenkungsvertrag und Auflassung werden notariell beurkundet; E unterschreibt allein, seine Eltern erfahren erst nach der Eintragung davon und halten das Geschäft wegen der Grundschuld für unwirksam.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Das Geschäft ist unwirksam, weil die Grundschuld E zur Zahlung von 50.000 € an die Bank verpflichtet und damit ein rechtlicher Nachteil ist (§ 107).", "Falsch. Die Grundschuld begründet keine persönliche Zahlungspflicht des E. E muss nur die Zwangsvollstreckung in das Grundstück dulden; das mindert den Vorteil, ist aber kein rechtlicher Nachteil."], ["Schenkung und Erwerb sind wirksam, weil die Belastung mit einer Grundschuld für E keinen rechtlichen Nachteil begründet (§ 107).", "Richtig. E haftet nicht persönlich, er riskiert nur den Verlust des geschenkten Grundstücks selbst. Nach dem BGH ist der Erwerb daher lediglich rechtlich vorteilhaft."], ["Das Geschäft ist unwirksam, weil der Wert des Grundstücks durch die Grundschuld wirtschaftlich gemindert ist (§ 107).", "Falsch. Bei § 107 kommt es auf die rechtliche, nicht auf die wirtschaftliche Betrachtung an."], ["Das Geschäft ist wirksam, aber nur, weil der Notar die Beurkundung vorgenommen und damit die Eltern ersetzt hat (§ 311b I).", "Falsch. Die notarielle Form ersetzt keine erforderliche Zustimmung der Eltern. Hier braucht es sie nur deshalb nicht, weil das Geschäft lediglich vorteilhaft ist."], ["Das Geschäft ist wirksam, weil Schenkungen an Minderjährige ab 16 Jahren stets ohne Zustimmung der Eltern möglich sind (§ 2229 I).", "Falsch. § 2229 I betrifft die Testierfähigkeit ab 16, nicht Schenkungen. Für Schenkungen gilt allein § 107."], ["Das Geschäft ist schwebend unwirksam, weil E als Eigentümer künftig die Grundsteuer zahlen muss und das ein rechtlicher Nachteil ist (§ 107).", "Falsch. Laufende öffentliche Lasten wie die Grundsteuer sind typisch und gering; der BGH lässt sie bei der Prüfung des § 107 außer Betracht."]], "id": "P5-28", "tag": "Neu · Transfer", "neu": true}, {"topic": "per", "sv": "Der 17-jährige Leon schließt ohne Wissen seiner Eltern einen Zwei-Jahres-Vertrag mit dem Fitnessstudio F über 39 € monatlich. Die ersten drei Beiträge zahlt er von seinem eigenen Konto. Drei Monate nach Vertragsschluss wird er 18. Das Studio erfährt jetzt erst sein Alter und schreibt ihm: „Bitte teilen Sie uns mit, ob Sie den Vertrag genehmigen.“ Leon reagiert nicht, geht aber auch nicht mehr hin. Nach drei Wochen verlangt F die Beiträge.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Der Vertrag ist wirksam, weil Leon mit Eintritt der Volljährigkeit automatisch an alle vorher geschlossenen Verträge gebunden ist.", "Falsch. Eine automatische Wirksamkeit gibt es nicht. Nach § 108 III tritt seine eigene Genehmigung an die Stelle der Genehmigung der Eltern – er muss sie erklären."], ["Der Vertrag ist weiter schwebend unwirksam, weil nur die Eltern ihn genehmigen können, die aber nicht gefragt wurden (§ 108 I).", "Falsch. Mit Volljährigkeit sind die Eltern nicht mehr zuständig. Genehmigen kann jetzt nur noch Leon selbst (§ 108 III)."], ["Der Vertrag ist wirksam, weil Leon die Beiträge in den ersten drei Monaten widerspruchslos gezahlt hat und das als Genehmigung gilt.", "Falsch. Die Zahlungen leistete Leon als Minderjähriger – damals konnte er gar nicht selbst genehmigen. Eine Genehmigung durch schlüssiges Verhalten setzt zudem voraus, dass er die Schwebelage kannte."], ["Der Vertrag ist endgültig unwirksam, weil Leon auf die Aufforderung nicht binnen zwei Wochen genehmigt hat (§ 108 II, III).", "Richtig. Nach Volljährigkeit entscheidet Leon selbst (§ 108 III). Auf die Aufforderung des Studios gilt sein Schweigen nach zwei Wochen als Verweigerung (§ 108 II 2)."], ["Der Vertrag ist endgültig unwirksam, aber erst, weil Leon das Studio nicht mehr besucht hat und damit konkludent gekündigt hat.", "Falsch. Ergebnis richtig, Begründung falsch: Das Fernbleiben ist keine Kündigung. Unwirksam ist der Vertrag wegen der als verweigert geltenden Genehmigung."], ["Der Vertrag ist wirksam, weil das Studio ohne Kenntnis vom Alter gutgläubig war (§ 932 analog).", "Falsch. Der gute Glaube an die Volljährigkeit wird im BGB nicht geschützt. § 932 betrifft den Erwerb beweglicher Sachen."]], "id": "P5-29", "tag": "Neu · Transfer", "neu": true}, {"topic": "typ", "sv": "Vermieterin V vermietet Student S eine Wohnung für 800 € Kaltmiete zuzüglich 150 € Betriebskostenvorauszahlung. Im Mietvertrag steht: „Der Mieter leistet bei Vertragsschluss eine Kaution von vier Monatsmieten inklusive Nebenkosten (3.800 €), zahlbar sofort in einer Summe.“ S unterschreibt, zahlt aber zum Mietbeginn nur 800 € und will den Rest in zwei weiteren Raten zahlen. V droht mit fristloser Kündigung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["S muss 3.800 € sofort zahlen, weil er die Klausel unterschrieben hat und Vertragsfreiheit gilt (§ 311 I).", "Falsch. § 551 IV: Eine zum Nachteil des Mieters abweichende Vereinbarung ist unwirksam. Die Vertragsfreiheit ist hier gesetzlich begrenzt."], ["S schuldet 2.850 €, also drei Monatsmieten einschließlich Betriebskostenvorauszahlung, in einer Summe (§ 551 I).", "Falsch. Die Höchstgrenze bemisst sich nach der Miete ohne die als Pauschale oder Vorauszahlung ausgewiesenen Betriebskosten. Außerdem darf S in Raten zahlen."], ["Die ganze Kautionsvereinbarung ist nichtig, sodass S überhaupt keine Kaution schuldet (§§ 134, 139).", "Falsch. Nach dem BGH bleibt die Kautionsabrede bis zur zulässigen Höhe wirksam; nur der übersteigende Teil ist unwirksam."], ["S schuldet 2.400 €, muss sie aber vollständig bei Mietbeginn zahlen, weil Ratenzahlung vereinbart werden muss (§ 551 II).", "Falsch. Das Recht auf drei Raten folgt unmittelbar aus dem Gesetz (§ 551 II 1); einer Vereinbarung bedarf es nicht."], ["V darf fristlos kündigen, weil S mit einem Teil der Kaution in Verzug ist (§ 569 IIa).", "Falsch. § 569 IIa verlangt einen Rückstand in Höhe von zwei Nettokaltmieten. S hat die erste zulässige Rate gezahlt und ist mit nichts in Verzug."], ["S schuldet höchstens 2.400 €, zahlbar in drei Monatsraten; die erste hat er bereits geleistet (§ 551 I, II).", "Richtig. Höchstens drei Monatsmieten ohne Betriebskosten (3 × 800 €). Der Mieter darf in drei Raten zahlen, die erste ist zu Beginn des Mietverhältnisses fällig."]], "id": "P5-30", "tag": "Neu · Transfer", "neu": true}, {"topic": "typ", "sv": "Bauherrin B beauftragt Malermeister M, für 10.000 € alle Innenräume ihres Hauses zu streichen. Nachdem M zwei von fünf Räumen fertiggestellt hat (Wert 4.000 €), kündigt B den Vertrag ohne Begründung, weil sie den Rest nun von ihrem Schwager machen lassen will. Für die restlichen Räume hätte M noch Farbe für 500 € gekauft; einen anderen Auftrag kann er so kurzfristig nicht annehmen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["B kann ohne wichtigen Grund gar nicht kündigen; der Vertrag besteht fort und M kann weiterarbeiten (§ 648a).", "Falsch. § 648a betrifft die Kündigung aus wichtigem Grund. Der Besteller kann daneben nach § 648 jederzeit ohne Grund kündigen."], ["B kann kündigen und schuldet nur die 4.000 € für die bereits gestrichenen Räume (§ 648 S. 1).", "Falsch. § 648 S. 2 gibt dem Unternehmer die volle vereinbarte Vergütung abzüglich ersparter Aufwendungen, nicht nur den Wert des Geleisteten."], ["B kann jederzeit kündigen, schuldet aber 9.500 €: Vergütung minus ersparte Aufwendungen (§ 648 S. 2).", "Richtig. Die Kündigung ist wirksam. M behält seinen Vergütungsanspruch, muss sich aber Ersparnisse (Farbe 500 €) und anderweitigen Erwerb anrechnen lassen – den gibt es hier nicht."], ["B kann kündigen und schuldet 4.300 €: die 4.000 € plus 5 % der Vergütung für den nicht erbrachten Teil (§ 648 S. 3).", "Falsch. Die 5 %-Pauschale ist nur eine Vermutung für den Fall, dass M seinen konkreten Anspruch nicht darlegt. Hier sind die Ersparnisse bekannt; M kann mehr verlangen."], ["B kann kündigen, schuldet aber nichts, weil das Werk nicht vollendet und deshalb nicht abnahmefähig ist (§ 641).", "Falsch. Auf die Abnahme kommt es nicht an. § 648 S. 2 ist ein eigener Vergütungsanspruch nach Kündigung."], ["B kann kündigen und schuldet 10.000 € voll, weil ersparte Aufwendungen nur beim Rücktritt abgezogen werden (§ 346).", "Falsch. § 648 S. 2 ordnet den Abzug ersparter Aufwendungen ausdrücklich an. § 346 betrifft den Rücktritt."]], "id": "P5-31", "tag": "Neu · Transfer", "neu": true}, {"topic": "typ", "sv": "Abiturient A bucht beim Nachhilfelehrer N zehn Doppelstunden Mathematik zu je 50 €. Im Vertrag steht: „Ziel: Vorbereitung auf das Mathe-Abitur.“ N erscheint pünktlich, erklärt den Stoff sorgfältig und bearbeitet mit A alte Prüfungen. A fällt im Abitur trotzdem mit 3 Punkten durch. Seine Eltern verweigern die Zahlung der letzten fünf Stunden: Der „Erfolg“ sei ausgeblieben, außerdem sei die Leistung mangelhaft gewesen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["A muss zahlen, weil N nur die Unterrichtstätigkeit schuldete, nicht das Bestehen des Abiturs (§§ 611, 614).", "Richtig. Nachhilfe ist ein Dienstvertrag: Geschuldet ist die sorgfältige Tätigkeit, nicht ein Erfolg. Die Vergütung ist nach Leistung der Dienste fällig."], ["A muss nicht zahlen, weil der vereinbarte Erfolg „Abitur“ ausgeblieben ist und der Werklohn erst mit Abnahme fällig wird (§§ 631, 641).", "Falsch. Das Bestehen der Prüfung hängt von A selbst ab und kann nicht geschuldet sein. Das „Ziel“ im Vertrag beschreibt nur den Zweck der Dienste."], ["A kann die Vergütung mindern, weil die Leistung nicht zum gewünschten Ergebnis geführt hat (§ 638).", "Falsch. Eine Minderung kennt das Dienstvertragsrecht nicht; § 638 gilt für Werkverträge. Außerdem hat N ordnungsgemäß unterrichtet."], ["A muss nur zahlen, wenn N die Stunden schriftlich dokumentiert hat, weil Dienstverträge der Textform bedürfen (§ 126b).", "Falsch. Dienstverträge sind formfrei. Eine Dokumentation kann beim Beweis helfen, ist aber keine Wirksamkeitsvoraussetzung."], ["A muss nicht zahlen, weil Verträge über Unterricht mit Minderjährigen der Genehmigung des Familiengerichts bedürfen.", "Falsch. Eine familiengerichtliche Genehmigung ist dafür nicht vorgesehen. Hier haben ohnehin die Eltern den Vertrag mitgetragen."], ["A muss zahlen, aber nur die Hälfte, weil N das Risiko des Nichtbestehens teilweise mitträgt (§ 254).", "Falsch. Eine Risikoteilung sieht das Gesetz nicht vor. § 254 betrifft Mitverschulden bei Schadensersatzansprüchen, nicht den Vergütungsanspruch."]], "id": "P5-32", "tag": "Neu · Transfer", "neu": true}, {"topic": "typ", "sv": "Angestellte A nimmt am 3. März bei ihrer Bank B ein Darlehen über 12.000 € für ein neues Auto auf. Der Vertrag wird in den Räumen der Bank schriftlich geschlossen; A erhält alle vorgeschriebenen Pflichtangaben und eine ordnungsgemäße Widerrufsbelehrung. Am 12. März überlegt sie es sich anders, weil ihre Eltern ihr das Geld zinslos leihen wollen, und erklärt gegenüber B den Widerruf. B meint, im stationären Bankgeschäft gebe es kein Widerrufsrecht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["A kann nicht widerrufen, weil der Vertrag nicht im Fernabsatz, sondern in den Geschäftsräumen der Bank geschlossen wurde (§ 312g).", "Falsch. Das Widerrufsrecht beim Verbraucherdarlehen folgt aus § 495 I und gilt unabhängig davon, wo der Vertrag geschlossen wurde. § 312g betrifft andere Vertriebsformen."], ["A kann widerrufen, muss aber eine Vorfälligkeitsentschädigung zahlen, weil sie das Darlehen vor Ablauf der Laufzeit beendet (§ 502).", "Falsch. § 502 betrifft die vorzeitige Rückzahlung eines wirksamen Darlehens. Beim Widerruf wird der Vertrag rückabgewickelt; eine Vorfälligkeitsentschädigung fällt nicht an."], ["A kann nicht widerrufen, weil sie das Darlehen bereits erhalten hat und das Widerrufsrecht mit der Auszahlung erlischt.", "Falsch. Ein Erlöschen durch Auszahlung sieht das Gesetz für Verbraucherdarlehen nicht vor. Die Auszahlung führt nur dazu, dass A das Geld beim Widerruf zurückzahlen muss."], ["A kann widerrufen, aber nur innerhalb einer Woche nach Vertragsschluss (§ 355 II).", "Falsch. Die Widerrufsfrist beträgt 14 Tage (§ 355 II 1), nicht eine Woche."], ["A kann binnen 14 Tagen widerrufen; der Widerruf am 12. März ist rechtzeitig (§§ 495 I, 355 II).", "Richtig. Beim Verbraucherdarlehensvertrag hat der Darlehensnehmer ein Widerrufsrecht. Die Frist von 14 Tagen begann mit Vertragsschluss und Erhalt der Pflichtangaben am 3. März."], ["A kann widerrufen, weil der Vertrag mangels notarieller Beurkundung ohnehin formnichtig ist (§§ 492, 125).", "Falsch. § 492 verlangt die Schriftform, nicht die notarielle Beurkundung. Der Vertrag ist formwirksam; der Widerruf ist ein eigenes Recht."]], "id": "P5-33", "tag": "Neu · Transfer", "neu": true}, {"topic": "agb", "sv": "Fotografin F kauft im Onlineshop des Händlers H einen Fotodrucker für 299 €. Vor dem Bestellbutton bestätigt sie per Häkchen, die AGB gelesen zu haben. Auf Seite 7 der zwölfseitigen AGB steht unter der Überschrift „Datenschutz“: „Mit dem Kauf verpflichtet sich der Kunde, für 24 Monate monatlich ein Tinten-Abo zu 29,90 € zu beziehen.“ Auf der Produktseite und in der Bestellübersicht war davon keine Rede. H schickt die erste Abo-Rechnung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["F muss das Abo bezahlen, weil sie die Einbeziehung der AGB durch das Häkchen ausdrücklich bestätigt hat (§ 305 II).", "Falsch. Die wirksame Einbeziehung nach § 305 II reicht nicht. Überraschende Klauseln werden trotzdem nicht Vertragsbestandteil (§ 305c I)."], ["Das Abo ist wirksam, F kann es aber jederzeit mit einer Frist von einem Monat kündigen (§ 309 Nr. 9).", "Falsch. Die Klausel ist schon gar nicht Vertragsbestandteil geworden. Auf Kündigungsregeln kommt es deshalb nicht an."], ["Der ganze Kaufvertrag ist unwirksam, weil er eine unwirksame AGB-Klausel enthält (§ 139).", "Falsch. Bei AGB gilt die Sonderregel des § 306 I: Der Vertrag bleibt im Übrigen wirksam, nur die Klausel fällt weg."], ["Die Abo-Klausel ist nicht Vertragsbestandteil geworden, weil sie so ungewöhnlich ist, dass F mit ihr nicht rechnen musste; der Kauf bleibt bestehen (§ 305c I).", "Richtig. Eine kostenpflichtige Abo-Pflicht beim Kauf eines Druckers ist ungewöhnlich, noch dazu unter „Datenschutz“ versteckt. Der Kaufvertrag bleibt im Übrigen wirksam (§ 306 I)."], ["Die Klausel ist wirksam, weil F als Fotografin Unternehmerin ist und gegenüber Unternehmern keine AGB-Kontrolle stattfindet (§ 310 I).", "Falsch. § 310 I schränkt nur §§ 305 II, III, 308, 309 ein. § 305c I gilt auch gegenüber Unternehmern. Ob F hier überhaupt beruflich kaufte, kann offenbleiben."], ["Die Klausel ist unwirksam, aber F muss den Drucker zurückgeben, weil H ihn ohne Abo nicht verkauft hätte (§ 306 III).", "Falsch. § 306 III (Unwirksamkeit des ganzen Vertrags) greift nur, wenn das Festhalten eine unzumutbare Härte wäre. Dass H mit dem Abo verdienen wollte, genügt nicht."]], "id": "P5-34", "tag": "Neu · Transfer", "neu": true}, {"topic": "agb", "sv": "Verbraucher V bestellt im Onlineshop des Schreiners S einen Esstisch aus Eiche. Im Konfigurator wählt er Länge 2,15 m, Breite 0,95 m, Tischbeine aus Stahl und eine eingravierte Widmung mit den Namen seiner Kinder. S fertigt den Tisch und liefert. Nach einer Woche gefällt V der Farbton nicht mehr; er erklärt den Widerruf.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["V kann widerrufen, weil er den Tisch im Fernabsatz gekauft hat und jeder Fernabsatzvertrag ein Widerrufsrecht gibt (§ 312g I).", "Falsch. „Jeder“ stimmt nicht: § 312g II enthält Ausnahmen, darunter Waren, die nach Kundenspezifikation angefertigt werden."], ["V kann nicht widerrufen, weil der Tisch nach seinen individuellen Vorgaben angefertigt wurde (§ 312g II Nr. 1).", "Richtig. Maße, Beine und Gravur hat V individuell bestimmt. Für solche Waren ist das Widerrufsrecht ausgeschlossen; S könnte den Tisch kaum anderweitig verkaufen."], ["V kann widerrufen, muss aber Wertersatz in Höhe des vollen Kaufpreises leisten, weil der Tisch unverkäuflich ist.", "Falsch. Ein Widerrufsrecht besteht gar nicht. Auf Wertersatz kommt es deshalb nicht an."], ["V kann nicht widerrufen, weil Möbel wegen ihrer Größe generell vom Widerrufsrecht ausgenommen sind.", "Falsch. Sperrige Waren sind nicht ausgeschlossen; es fallen nur besondere Rücksendekosten an. Der Ausschluss folgt hier aus der individuellen Anfertigung."], ["V kann widerrufen, weil ihm ein Gefallen am Farbton eines Holztischs nicht vorher zugemutet werden kann (§ 312g I).", "Falsch. Der Farbton ist kein Grund, der den gesetzlichen Ausschluss überwindet. Ein Widerruf braucht ohnehin keinen Grund – hier ist er aber ausgeschlossen."], ["V kann nicht widerrufen, weil die Widerrufsfrist bei Werkverträgen nur drei Tage beträgt (§ 355 II).", "Falsch. Die Frist beträgt immer 14 Tage (§ 355 II 1). Das Problem ist nicht die Frist, sondern der Ausschluss nach § 312g II Nr. 1."]], "id": "P5-35", "tag": "Neu · Transfer", "neu": true}, {"topic": "anf", "sv": "Elektrikerin E erstellt für Bauherr B ein schriftliches Angebot über die Elektroinstallation seines Neubaus: „Pauschalpreis 18.000 € netto.“ Bei der Berechnung hat sie in ihrer Tabelle versehentlich die Kabelkosten für das Obergeschoss vergessen; richtig wären 22.000 € gewesen. Die Kalkulation hat sie B nicht vorgelegt, und B hatte keinen Anlass, an dem Preis zu zweifeln. B nimmt an. Als E den Fehler bemerkt, erklärt sie die Anfechtung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Die Anfechtung ist wirksam, weil E sich über den Inhalt ihrer Erklärung geirrt hat: Sie wollte einen kostendeckenden Preis anbieten (§ 119 I Alt. 1).", "Falsch. E wollte genau „18.000 €“ erklären und hat das auch getan. Der Fehler liegt in der Berechnung davor, nicht im Inhalt der Erklärung."], ["Die Anfechtung ist wirksam, weil die Kosten eines Werks eine verkehrswesentliche Eigenschaft sind (§ 119 II).", "Falsch. Der Preis bzw. die eigenen Kosten sind keine Eigenschaft der Leistung im Sinne des § 119 II. Es handelt sich um einen Kalkulationsirrtum."], ["Die Anfechtung ist wirksam, E muss B aber den Vertrauensschaden ersetzen (§§ 119 I, 122).", "Falsch. Ergebnis zur Haftung wäre bei wirksamer Anfechtung richtig, aber es fehlt schon an einem Anfechtungsgrund."], ["Die Anfechtung ist wirksam, weil B einen offensichtlich zu niedrigen Preis nicht annehmen durfte (§ 242).", "Falsch. Laut Sachverhalt hatte B keinen Anlass zu Zweifeln. Erst wenn der Vertragspartner den Fehler kennt und treuwidrig ausnutzt, kommt ein Schutz über § 242 in Betracht."], ["Der Vertrag ist nichtig, weil sich beide über die Kalkulationsgrundlage nicht geeinigt haben (§ 155).", "Falsch. Beide haben sich über einen Pauschalpreis von 18.000 € geeinigt. Die interne Kalkulation war nie Gegenstand der Verhandlungen."], ["Die Anfechtung ist unwirksam: Ein verdeckter Kalkulationsirrtum ist ein bloßer Motivirrtum (§ 119).", "Richtig. E hat erklärt, was sie erklären wollte. Der Fehler in der Berechnung betrifft nur ihre Beweggründe. Das Kalkulationsrisiko trägt der Anbietende."]], "id": "P5-36", "tag": "Neu · Transfer", "neu": true}, {"topic": "anf", "sv": "Kioskbesitzer K wird im März von seinem Vermieter V unter Druck gesetzt: Wenn er nicht sofort einen Nachtrag mit 30 % höherer Miete unterschreibe, werde V eine ihm bekannte frühere Steuerhinterziehung des K beim Finanzamt anzeigen. K unterschreibt aus Angst. V droht noch bis Ende Juni weiter. Im Juli zieht V in eine andere Stadt und meldet sich nie wieder. Im April des folgenden Jahres erklärt K die Anfechtung des Nachtrags.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Die Anfechtung ist verfristet, weil die Jahresfrist mit der Abgabe der Erklärung im März begann (§ 124 I).", "Falsch. Bei Drohung beginnt die Frist nicht mit der Erklärung, sondern mit dem Ende der Zwangslage (§ 124 II 1)."], ["Die Anfechtung ist verfristet, weil wegen Drohung unverzüglich nach Kenntnis angefochten werden muss (§ 121).", "Falsch. § 121 gilt nur für §§ 119, 120. Für § 123 gilt die Jahresfrist des § 124."], ["Rechtzeitig: Bei Drohung beginnt die Jahresfrist erst mit dem Ende der Zwangslage (§ 124 II).", "Richtig. Die Zwangslage dauerte, solange V drohte – bis Ende Juni bzw. bis zu seinem Wegzug im Juli. Die Anfechtung im April des Folgejahres liegt innerhalb eines Jahres."], ["Die Anfechtung ist unzulässig, weil die Anzeige einer tatsächlich begangenen Straftat erlaubt ist und deshalb keine widerrechtliche Drohung sein kann (§ 123 I).", "Falsch. Widerrechtlich ist die Drohung hier wegen der Zweck-Mittel-Relation: Die Anzeige einer Steuerstraftat hat mit der Mieterhöhung nichts zu tun; sie als Druckmittel für einen fremden Vorteil einzusetzen, ist verwerflich."], ["Die Anfechtung ist rechtzeitig, aber nur, weil Anfechtungen bei Mietverträgen an keine Frist gebunden sind.", "Falsch. Ergebnis richtig, Begründung falsch: Für die Anfechtung gelten auch bei Mietverträgen die Fristen der §§ 121, 124."], ["Die Anfechtung ist rechtzeitig, K muss V aber den Vertrauensschaden ersetzen (§ 122).", "Falsch. § 122 gilt nur bei Anfechtung nach §§ 119, 120. Wer droht, verdient keinen Vertrauensschutz."]], "id": "P5-37", "tag": "Neu · Transfer", "neu": true}, {"topic": "stv", "sv": "Im Malerbetrieb des Inhabers I bestellt der Geselle G seit einem Jahr regelmäßig im Namen des Betriebs Farbe und Werkzeug beim Großhändler H. Eine Vollmacht hat ihm I nie erteilt. I weiß von den Bestellungen, lässt G aber gewähren und bezahlt alle Rechnungen. Im Mai bestellt G wie üblich Farbe für 1.400 €. I hat sich inzwischen mit G zerstritten und verweigert die Zahlung: G habe nie Vertretungsmacht gehabt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["I muss zahlen, weil er das Auftreten des G wissentlich geduldet hat und H darauf vertrauen durfte (Duldungsvollmacht).", "Richtig. I kannte das wiederholte Handeln des G in seinem Namen und ließ es geschehen; H durfte das als Bevollmächtigung verstehen. I muss sich so behandeln lassen, als habe er Vollmacht erteilt."], ["I muss nicht zahlen, weil G ohne Vertretungsmacht gehandelt hat und I die Genehmigung verweigert (§ 177 I).", "Falsch. § 177 greift nur, wenn auch keine Rechtsscheinvollmacht besteht. Hier wirkt die Duldungsvollmacht wie eine erteilte Vollmacht."], ["I muss nicht zahlen; G haftet H persönlich auf Erfüllung, weil er den Mangel seiner Vollmacht kannte und H davon nichts wusste (§ 179 I).", "Falsch. § 179 setzt voraus, dass der Vertreter ohne Vertretungsmacht gehandelt hat. Die Duldungsvollmacht schließt diese Lücke; Vertragspartner ist I."], ["I muss zahlen, aber nur, weil G als Angestellter in einem Laden nach § 56 HGB als bevollmächtigt gilt.", "Falsch. Ergebnis richtig, Begründung falsch: § 56 HGB betrifft Verkäufe im Laden an Kunden, nicht Einkäufe bei Lieferanten."], ["I muss nicht zahlen, weil eine Vollmacht für wiederkehrende Bestellungen schriftlich erteilt werden muss (§ 167 II).", "Falsch. Die Vollmacht ist grundsätzlich formfrei (§ 167 II). Hier kommt es ohnehin auf den Rechtsschein an, nicht auf eine Erklärung."], ["I muss zahlen, kann den Vertrag aber anfechten, weil er sich über die Vertretungsmacht des G geirrt hat (§ 119 I).", "Falsch. I hat sich nicht geirrt, er wusste von den Bestellungen. Eine Anfechtung der Duldung scheidet nach h. M. aus."]], "id": "P5-38", "tag": "Neu · Transfer", "neu": true}];
L.forEach(q=>{ if(!W.some(x=>x.id===q.id)) W.push(q); });
window.WPR_LOES = Object.assign(window.WPR_LOES || {}, {"P5-0": {"k": "Kein Vertrag: Die ", "w": ["Frage: Ist durch die Annahme des S ein Vertrag zustande gekommen?", "Das Angebot war befristet bis Freitag (§ 148). Eine Annahme ist nur rechtzeitig, wenn sie G bis dahin zugeht (§ 130 I 1) – die Absendung zählt nicht.", "Der Brief ging erst am Samstag zu → verspätet. § 149 hilft nicht: Der Postlauf war normal, die Verspätung also nicht auf eine unregelmäßige Beförderung zurückzuführen.", "Folge: Die verspätete Annahme gilt als neues Angebot (§ 150 I). G hat es nicht angenommen; Schweigen ist keine Annahme.", "Ergebnis: c – kein Vertrag."]}, "P5-1": {"k": "Das Zahlungsziel i", "w": ["Frage: Ist das Zahlungsziel von 14 Tagen Vertragsinhalt geworden, obwohl M geschwiegen hat?", "Grundsatz: Schweigen ist keine Willenserklärung. Ausnahme unter Kaufleuten: das kaufmännische Bestätigungsschreiben (Handelsbrauch, § 346 HGB).", "Voraussetzungen: Kaufleute (beide GmbH, § 6 HGB), vorausgegangene Verhandlungen (Telefonat), Schreiben unmittelbar danach, das den Vertragsinhalt wiedergeben will, redlicher Absender, keine so erhebliche Abweichung, dass mit Ablehnung zu rechnen war – ein 14-tägiges Zahlungsziel ist üblich.", "M hat nicht unverzüglich widersprochen → das Schreiben gilt mit seinem Inhalt als vereinbart.", "Ergebnis: e ist richtig."]}, "P5-2": {"k": "Kein Vertrag: Der ", "w": ["Frage: Hat der Widerruf das Angebot verhindert?", "Eine Willenserklärung unter Abwesenden wird mit Zugang wirksam (§ 130 I 1). Zugang = Eingang im Machtbereich des Empfängers, sodass unter normalen Umständen mit Kenntnisnahme zu rechnen ist.", "Sie wird nicht wirksam, wenn dem Empfänger vorher oder gleichzeitig ein Widerruf zugeht (§ 130 I 2).", "E-Mail um 8:30 Uhr während der Geschäftszeit → zugegangen. Brief um 10 Uhr → später zugegangen. Wann tatsächlich gelesen wird, ist egal.", "Ergebnis: a – kein Vertrag, die Annahme geht ins Leere."]}, "P5-3": {"k": "Kein Vertrag: K ha", "w": ["Frage: Ist ein Kaufvertrag zu 49 € zustande gekommen?", "Ein Vertrag braucht Angebot und Annahme. Ist die Preisauszeichnung im Schaufenster schon ein Angebot? Nein: Der Händler will Vorrat, Zahlungsfähigkeit und Preisfehler noch prüfen können → invitatio ad offerendum.", "Das Angebot gibt K an der Kasse ab („für 49 €“). Die Kassiererin lehnt ab → keine Annahme.", "Ohne Vertrag stellt sich die Frage einer Anfechtung nicht.", "Ergebnis: d ist richtig."]}, "P5-4": {"k": "Ein formwirksamer ", "w": ["Frage: Worüber besteht ein Kaufvertrag – und ist er formwirksam?", "Auslegung (§§ 133, 157): Haben beide übereinstimmend dasselbe gewollt, gilt das Gewollte, auch wenn sie es falsch bezeichnen (falsa demonstratio non nocet). Beide wollten die Wiese (117).", "Form (§ 311b I 1): Der BGH lässt die falsche Bezeichnung in der Urkunde unschädlich sein – der Vertrag über das wirklich Gewollte gilt als beurkundet.", "Über das Waldstück besteht kein Vertrag, weil es niemand wollte; Dissens liegt nicht vor.", "Ergebnis: f – wirksamer Vertrag über die Wiese."]}, "P5-5": {"k": "Verzug 30 Tage nac", "w": ["Frage: Ist S ohne Mahnung in Verzug, und welche Zinsen und Pauschale gibt es?", "Verzug setzt grundsätzlich eine Mahnung voraus (§ 286 I) – Ausnahmen in § 286 II. Für Entgeltforderungen gibt es zusätzlich § 286 III: Verzug spätestens, wenn nicht innerhalb von 30 Tagen nach Fälligkeit und Zugang einer Rechnung gezahlt wird. Den Hinweis auf diese Folge braucht es nur bei Verbrauchern.", "Rechnung am 2. März zugegangen, Forderung fällig → Verzug nach Ablauf von 30 Tagen, also Anfang April. Am 20. April besteht er.", "Zinsen: Ist kein Verbraucher beteiligt, 9 Prozentpunkte über dem Basiszinssatz (§ 288 II). Pauschale: 40 €, wenn der Schuldner kein Verbraucher ist (§ 288 V).", "Ergebnis: b ist richtig."]}, "P5-6": {"k": "K kann nichts verl", "w": ["Frage: Bekommt K die Kosten seiner eigenmächtigen Reparatur ersetzt?", "Ein Sachmangel liegt vor (§ 434). Die Mängelrechte des § 437 stehen aber in einer Rangfolge: Zuerst muss der Käufer Nacherfüllung verlangen und dem Verkäufer Gelegenheit dazu geben („Recht zur zweiten Andienung“).", "Schadensersatz statt der Leistung bzw. Kostenersatz setzt grundsätzlich eine erfolglose Frist bzw. – beim Verbrauchsgüterkauf – eine Unterrichtung über den Mangel voraus (§§ 281 I, 475d). Beides fehlt.", "Der BGH gewährt auch keinen Ersatz ersparter Verkäuferkosten über § 326 II 2 analog, weil sonst der Vorrang der Nacherfüllung leerliefe.", "Ergebnis: d – K geht leer aus."]}, "P5-7": {"k": "J kann die Leistun", "w": ["Frage: Muss J leisten, muss K zahlen, und gibt es Schadensersatz?", "Leistungspflicht: Die Bergung ist möglich, aber der Aufwand (40.000 €) steht in grobem Missverhältnis zum Leistungsinteresse des K (Ringwert). Auch mit Rücksicht auf J's Verschulden (§ 275 II 2) → J darf verweigern (§ 275 II, Einrede).", "Gegenleistung: Wird der Schuldner nach § 275 frei, entfällt der Kaufpreis (§ 326 I 1). Gefahr war mangels Übergabe nicht übergegangen.", "Schadensersatz statt der Leistung (§§ 280 I, III, 283): J war fahrlässig (§ 276 I). Schaden nach Differenzmethode: 1.500 € Wiederbeschaffung minus 1.200 € ersparter Kaufpreis = 300 €.", "Ergebnis: e ist richtig."]}, "P5-8": {"k": "W muss nicht neu l", "w": ["Zwei Fragen: (1) Muss W neue Flaschen liefern? (2) Muss R zahlen?", "Zu (1): Gattungsschuld („60 Flaschen Riesling 2023“). Bei der Holschuld hat der Schuldner das seinerseits Erforderliche getan, wenn er die Ware aussondert, bereitstellt und den Gläubiger benachrichtigt → Konkretisierung (§ 243 II). Nur diese 60 Flaschen sind geschuldet; mit dem Diebstahl ist die Leistung unmöglich (§ 275 I).", "Zu (2): Grundsätzlich entfiele der Preis (§ 326 I). Aber R war im Annahmeverzug: Abholtermin war kalendermäßig bestimmt (§ 296). Im Annahmeverzug haftet W nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I) – die Türen waren gesichert.", "§ 326 II 1 Alt. 2: Unmöglichkeit während des Annahmeverzugs, vom Schuldner nicht zu vertreten → Kaufpreis bleibt.", "Ergebnis: a ist richtig."]}, "P5-9": {"k": "K kann die Maschin", "w": ["Frage: Kann K nach seinem Schadensersatzverlangen doch noch die Lieferung verlangen?", "Voraussetzungen des Schadensersatzes statt der Leistung (§§ 280 I, III, 281) liegen vor: fällige Leistung, Nichtleistung, erfolglose Frist, Vertretenmüssen vermutet.", "Nach Fristablauf hat K die Wahl: weiter Erfüllung verlangen oder Schadensersatz statt der Leistung. Hat er Schadensersatz verlangt, ist der Anspruch auf die Leistung ausgeschlossen (§ 281 IV).", "Der Gläubiger kann also nicht hin- und herwechseln; auf Zahlung oder Rücktritt kommt es nicht an.", "Ergebnis: c ist richtig."]}, "P5-10": {"k": "K muss die 80 € er", "w": ["Zwei Fragen: (1) Muss K die Lagerkosten zahlen? (2) Haftet M für den Kratzer?", "Annahmeverzug (§§ 293, 294): M hat die Leistung zur richtigen Zeit am richtigen Ort tatsächlich angeboten, K hat sie nicht angenommen. Verschulden der K ist nicht nötig.", "Zu (1): § 304 – der Schuldner kann Ersatz der Mehraufwendungen für das erfolglose Angebot und für Aufbewahrung verlangen → 80 €.", "Zu (2): § 300 I – während des Annahmeverzugs hat der Schuldner nur Vorsatz und grobe Fahrlässigkeit zu vertreten. Eine kleine Unachtsamkeit ist leichte Fahrlässigkeit → keine Rechte der K.", "Ergebnis: f ist richtig."]}, "P5-11": {"k": "F darf die Neulief", "w": ["Frage: Muss F neu liefern, oder darf er auf die Reparatur verweisen?", "Sachmangel bei Gefahrübergang (Fertigungsfehler, § 434). W wählt die Art der Nacherfüllung (§ 439 I) – hier Neulieferung.", "§ 439 IV: Der Verkäufer kann die gewählte Art verweigern, wenn sie nur mit unverhältnismäßigen Kosten möglich ist. Abzuwägen sind Wert der mangelfreien Sache, Bedeutung des Mangels und ob die andere Art ohne erhebliche Nachteile für den Käufer möglich ist.", "Pumpe in einem Tag für 180 € behebbar; Neulieferung 4.000 € → unverhältnismäßig. Das bloße Misstrauen gegenüber Reparaturen ist kein erheblicher Nachteil.", "Ergebnis: b – W kann nur Reparatur verlangen (§ 439 IV 3)."]}, "P5-12": {"k": "L kann neben den n", "w": ["Frage: Muss B neben der Neulieferung auch die Kosten für Ausbau und Neuverlegung tragen?", "Sachmangel bei Gefahrübergang (Brennfehler, § 434). L verlangt Nacherfüllung durch Neulieferung (§§ 437 Nr. 1, 439 I).", "§ 439 III: Hat der Käufer die Sache ihrer Art und ihrem Verwendungszweck gemäß eingebaut, bevor der Mangel offenbar wurde, muss der Verkäufer die erforderlichen Aufwendungen für Ausbau und Einbau ersetzen.", "Die Vorschrift gilt für alle Kaufverträge (nicht nur Verbraucher) und setzt kein Verschulden voraus. Fliesen werden typischerweise verlegt; die Risse waren vorher nicht erkennbar.", "Ergebnis: d ist richtig."]}, "P5-13": {"k": "Es wird vermutet, ", "w": ["Frage: Wer muss beweisen, dass der Defekt schon bei Übergabe vorlag?", "Grundsatz: Der Käufer muss beweisen, dass der Mangel bei Gefahrübergang vorlag.", "Verbrauchsgüterkauf (S Verbraucherin, E Unternehmer, § 474): Zeigt sich innerhalb eines Jahres seit Gefahrübergang ein vertragswidriger Zustand, wird vermutet, dass er schon bei Gefahrübergang bestand (§ 477 I; bis 2021 waren es sechs Monate).", "Januar → November: innerhalb eines Jahres. E kann die Vermutung nur durch Gegenbeweis widerlegen; ist die Ursache unaufklärbar, geht das zu seinen Lasten.", "Ergebnis: a ist richtig."]}, "P5-14": {"k": "Rücktritt scheidet", "w": ["Frage: Welche Mängelrechte hat K wegen eines geringfügigen Mangels?", "Sachmangel bei Übergabe (§ 434) – auch Kleinigkeiten zählen. Frist zur Nacherfüllung ist erfolglos abgelaufen.", "Rücktritt (§§ 437 Nr. 2, 323): ausgeschlossen, wenn die Pflichtverletzung unerheblich ist (§ 323 V 2). 120 € bei 32.000 € liegen deutlich unter der Erheblichkeitsschwelle (Richtwert BGH: 5 % der Beseitigungskosten). Gleiches gilt für den großen Schadensersatz (§ 281 I 3).", "Minderung (§ 441 I): wird „statt zurückzutreten“ erklärt, aber § 441 I 2 sagt: Der Ausschluss des § 323 V 2 gilt nicht.", "Ergebnis: e – Minderung ja, Rücktritt nein."]}, "P5-15": {"k": "K kann mindern; V ", "w": ["Frage: Hat K trotz Gewährleistungsausschluss und nach 2,5 Jahren noch Mängelrechte?", "Sachmangel (Durchrostung, § 434 III). Unter Privatleuten ist ein Gewährleistungsausschluss grundsätzlich zulässig (§ 476 gilt nur beim Verbrauchsgüterkauf).", "§ 444: Auf den Ausschluss kann sich der Verkäufer nicht berufen, soweit er den Mangel arglistig verschwiegen hat. V kannte das Loch, hatte es überlackiert und schwieg → Arglist.", "Verjährung: Bei Arglist nicht zwei Jahre ab Ablieferung, sondern regelmäßige Verjährung (§ 438 III 1): drei Jahre ab Schluss des Jahres der Kenntnis (§§ 195, 199 I) → nicht verjährt.", "Ergebnis: c ist richtig."]}, "P5-16": {"k": "C kann Lieferung d", "w": ["Frage: Welche Rechte hat C nach der Falschlieferung?", "Geschuldet war Modell Duo. Geliefert wurde ein anderes Modell (aliud). Eine Erfüllung (§ 362) tritt dadurch nicht ein.", "§ 434 V: Einem Sachmangel steht es gleich, wenn der Verkäufer eine andere als die geschuldete Sache liefert. Damit gelten die Rechte aus § 437.", "Vorrang der Nacherfüllung: C verlangt Lieferung der richtigen Maschine (§ 439 I); die falsche muss sie zurückgeben (§ 439 V). Ein Widerrufsrecht hat sie als Unternehmerin nicht.", "Ergebnis: b ist richtig."]}, "P5-17": {"k": "H kann von C 300 €", "w": ["Anspruch H gegen C aus § 812 I 1 Alt. 2 (Eingriffskondiktion) – Frage: Was hat C erlangt und was muss er zahlen?", "Leistung scheidet aus: H hat C nichts bewusst zugewendet. C hat aber in eine Rechtsposition eingegriffen, deren Nutzung allein H zusteht (Zuweisungsgehalt des Urheber- bzw. Nutzungsrechts) – ohne Rechtsgrund.", "Erlangt ist der Gebrauch des Fotos. Er kann nicht herausgegeben werden → Wertersatz (§ 818 II), bemessen nach der üblichen Lizenzgebühr: 300 €. Auf einen Schaden der H kommt es nicht an.", "Entreicherung (§ 818 III) scheidet aus: C hat sich die Lizenzgebühr erspart; der geringe Werbeerfolg ändert daran nichts. (Daneben bestehen urheberrechtliche Ansprüche, § 97 UrhG.)", "Ergebnis: d ist richtig."]}, "P5-18": {"k": "S durfte dem auf f", "w": ["Frage: Durfte S sich das Rad mit Gewalt zurückholen?", "S war unmittelbare Besitzerin (§ 854 I). Der Dieb hat ihr den Besitz ohne ihren Willen entzogen → verbotene Eigenmacht (§ 858 I); sein Besitz ist fehlerhaft.", "§ 859 II (Besitzkehr): Wird dem Besitzer eine bewegliche Sache durch verbotene Eigenmacht weggenommen, darf er sie dem auf frischer Tat betroffenen oder verfolgten Täter mit Gewalt wieder abnehmen. S hat sofort verfolgt.", "Die Gewalt war nicht übermäßig (Arm ziehen) → gerechtfertigt; kein Schadensersatz. § 229 ist daneben nicht nötig.", "Ergebnis: f ist richtig."]}, "P5-19": {"k": "R kann Unterlassun", "w": ["Frage: Kann R gegen den wiederholten Werbeeinwurf vorgehen?", "Anspruchsgrundlage: § 1004 I (Eigentum am Briefkasten) bzw. § 862 I (Besitzstörung). Voraussetzungen: Beeinträchtigung, Störer, Rechtswidrigkeit (keine Duldungspflicht, § 1004 II), Wiederholungsgefahr.", "Der Einwurf gegen den deutlich erklärten Willen beeinträchtigt die Sachherrschaft über den Briefkasten (BGH). Mit dem Aufkleber entfällt jede Duldungspflicht.", "Störer ist P, weil P die Verteilung veranlasst. Wiederholungsgefahr ergibt sich aus den wöchentlichen Einwürfen trotz Beanstandung. Schaden oder Verschulden sind nicht nötig.", "Ergebnis: a ist richtig."]}, "P5-20": {"k": "B hat gutgläubig E", "w": ["Frage: Wem gehört der gestohlene Geldschein nach dem Bezahlen beim Bäcker?", "D war Nichtberechtigter. Übereignung an B nach § 929 S. 1 (Einigung + Übergabe) i. V. m. § 932 I – B war gutgläubig.", "Grundsätzlich wäre der Erwerb ausgeschlossen, weil der Schein R gestohlen wurde, also abhandengekommen ist (§ 935 I).", "Ausnahme § 935 II: Die Sperre gilt nicht für Geld, Inhaberpapiere und Sachen aus öffentlicher Versteigerung. Hintergrund: Geld muss umlauffähig bleiben.", "Ergebnis: e – B ist Eigentümer; R hat Ansprüche gegen D (§§ 823, 812, 816 I 1)."]}, "P5-21": {"k": "S ist durch Verarb", "w": ["Frage: Wem gehört der Tisch, und was kann E verlangen?", "Erwerb der Bohlen: D war Nichtberechtigter, S gutgläubig – aber die Bohlen waren gestohlen (§ 935 I) → kein gutgläubiger Erwerb.", "Verarbeitung (§ 950 I): Wer durch Verarbeitung eine neue bewegliche Sache herstellt, wird Eigentümer, sofern der Wert der Verarbeitung nicht erheblich geringer ist als der Stoffwert. Tisch 4.500 € vs. Bohlen 400 € → S wird Eigentümer, und zwar kraft Gesetzes (§ 935 gilt nicht).", "Ausgleich: E kann nach § 951 I i. V. m. § 812 I 1 Alt. 2 Vergütung in Geld verlangen. Den an D gezahlten Preis darf S nach dem BGH nicht abziehen (Jungbullenfall).", "Ergebnis: b ist richtig."]}, "P5-22": {"k": "Die Abtretung ist ", "w": ["Frage: Ist die Abtretung trotz Verbot wirksam, und wurde A durch Zahlung an Z frei?", "Grundsatz § 399: Eine Forderung kann nicht abgetreten werden, wenn das mit dem Schuldner vereinbart ist.", "Ausnahme § 354a I HGB: Ist das Geschäft für beide Teile ein Handelsgeschäft (Z GmbH und A AG sind Kaufleute, § 6 HGB), ist die Abtretung trotz Verbots wirksam (S. 1). Der Schuldner kann aber mit befreiender Wirkung an den bisherigen Gläubiger leisten (S. 2) – auch wenn er von der Abtretung weiß.", "A hat an Z gezahlt → A ist frei. B hat gegen Z einen Anspruch auf das Erlangte (§ 816 II bzw. aus dem Finanzierungsvertrag).", "Ergebnis: c ist richtig."]}, "P5-23": {"k": "L haftet als Tierh", "w": ["Anspruch P gegen L – Frage: Haftet L ohne eigenes Verschulden?", "§ 833 S. 1: Wird durch ein Tier ein Mensch verletzt, ist der Halter zum Ersatz verpflichtet – Gefährdungshaftung, kein Verschulden nötig. Es muss sich die typische Tiergefahr (unberechenbares Verhalten) verwirklicht haben – das Schnappen aus Schreck ist dafür typisch.", "Entlastung (§ 833 S. 2) nur bei Haustieren, die dem Beruf, der Erwerbstätigkeit oder dem Unterhalt des Halters dienen (Nutztiere). Bella ist ein privates „Luxustier“ → keine Entlastung.", "Umfang: Heilungskosten (§ 249) und Schmerzensgeld wegen Körperverletzung (§ 253 II), auch bei Gefährdungshaftung.", "Ergebnis: d ist richtig."]}, "P5-24": {"k": "L kann von A 20.00", "w": ["Frage: Kann L ihren reinen Vermögensschaden von A ersetzt verlangen, obwohl kein Vertrag besteht?", "§ 823 I schützt nur absolute Rechte (Leben, Körper, Eigentum usw.), nicht das Vermögen als solches. Eigentum ist bei einer Überweisung nicht betroffen.", "§ 823 II: Wer gegen ein Gesetz verstößt, das den Schutz eines anderen bezweckt, haftet auf Schadensersatz. § 263 StGB (Betrug) schützt das Vermögen des Einzelnen → Schutzgesetz. A hat vorsätzlich getäuscht, einen Irrtum erregt, L hat verfügt und einen Schaden erlitten.", "Daneben § 826 (vorsätzliche sittenwidrige Schädigung). Eine strafrechtliche Verurteilung ist nicht Voraussetzung.", "Ergebnis: a – 20.000 €."]}, "P5-25": {"k": "K kann aus dem Ver", "w": ["Frage: Gibt es Schmerzensgeld aus dem Vertrag, und muss F für die Azubi einstehen?", "Vertraglicher Anspruch (§ 280 I): Schuldverhältnis (Friseurvertrag), Pflichtverletzung (zu lange Einwirkzeit), Vertretenmüssen.", "Vertretenmüssen: Die Azubi ist Erfüllungsgehilfin; ihr Verschulden wird F zugerechnet (§ 278) – ohne Entlastungsmöglichkeit (die gibt es nur bei § 831).", "Umfang: § 253 II – ist wegen Verletzung des Körpers oder der Gesundheit Schadensersatz zu leisten, gibt es auch Schmerzensgeld, unabhängig davon, ob der Anspruch aus Vertrag oder Delikt folgt (seit 2002).", "Ergebnis: f ist richtig."]}, "P5-26": {"k": "E kann von A alles", "w": ["Frage: Wie viel kann E von A verlangen?", "A und B haben vorsätzlich bzw. jedenfalls fahrlässig das Eigentum des E verletzt (§ 823 I). Als Mittäter haften beide für den ganzen Schaden (§ 830 I 1); notfalls hilft § 830 I 2, wenn sich der Verursacher nicht feststellen lässt.", "§ 840 I: Sind mehrere für denselben Schaden verantwortlich, haften sie als Gesamtschuldner. § 421: Der Gläubiger kann von jedem die ganze Leistung fordern, insgesamt aber nur einmal.", "Innenverhältnis: A kann von B Ausgleich verlangen, im Zweifel zu gleichen Teilen (§ 426 I, II).", "Ergebnis: c ist richtig."]}, "P5-27": {"k": "Der Rollerkauf ist", "w": ["Frage: Ist der Rollerkauf mit dem Gewinngeld wirksam?", "Mara ist beschränkt geschäftsfähig (§ 106). Teilnahme und Gewinnerwerb waren lediglich rechtlich vorteilhaft (§ 107) – das Geld gehört ihr. Der Rollerkauf verpflichtet sie aber zur Zahlung → zustimmungsbedürftig.", "§ 110 ersetzt die Einwilligung nur, wenn die Leistung mit Mitteln bewirkt wird, die der gesetzliche Vertreter (oder mit dessen Zustimmung ein Dritter) zu diesem Zweck oder zur freien Verfügung überlassen hat. Der Sender hat ohne Zustimmung der Eltern gezahlt → § 110 greift nicht.", "Ohne Einwilligung schwebend unwirksam (§ 108 I); die Eltern verweigern gegenüber Z (§ 182 I) → endgültig unwirksam. Rückabwicklung über §§ 812 ff.", "Ergebnis: e ist richtig."]}, "P5-28": {"k": "Schenkung und Erwe", "w": ["Frage: Ist der Erwerb eines mit einer Grundschuld belasteten Grundstücks für den 16-Jährigen lediglich rechtlich vorteilhaft?", "E ist beschränkt geschäftsfähig (§ 106) und konnte allein nur lediglich rechtlich vorteilhafte Geschäfte schließen (§ 107) – maßgeblich ist die rechtliche Betrachtung.", "Schenkungsvertrag (§ 516): nur ein Anspruch für E → vorteilhaft. Auflassung: Erwerb von Eigentum. Die Grundschuld verpflichtet E nicht persönlich zur Zahlung; er muss nur die Zwangsvollstreckung in das Grundstück dulden (§§ 1191, 1147). Er kann also schlimmstenfalls das Geschenk wieder verlieren, aber kein eigenes Vermögen.", "Nach dem BGH macht eine solche Belastung den Erwerb nicht rechtlich nachteilig (anders etwa bei Vermietung, § 566, oder bei Wohnungseigentum mit seinen Gemeinschaftspflichten).", "Ergebnis: b ist richtig."]}, "P5-29": {"k": "Der Vertrag ist en", "w": ["Frage: Ist der Fitnessvertrag nach Leons 18. Geburtstag wirksam geworden?", "Bei Abschluss war Leon beschränkt geschäftsfähig (§ 106); der Vertrag verpflichtet ihn zu Zahlungen → schwebend unwirksam (§§ 107, 108 I).", "Wird der Minderjährige volljährig, tritt seine Genehmigung an die Stelle der elterlichen (§ 108 III). Der Schwebezustand dauert an, bis er sich erklärt.", "Auf die Aufforderung des Vertragspartners gilt § 108 II entsprechend: Genehmigung nur binnen zwei Wochen nach Empfang; sonst gilt sie als verweigert. Leon schweigt drei Wochen → verweigert.", "Ergebnis: d – endgültig unwirksam; F hat keinen Beitragsanspruch."]}, "P5-30": {"k": "S schuldet höchste", "w": ["Frage: Welche Kaution schuldet S, und wann?", "§ 551 I: Die Sicherheit darf höchstens das Dreifache der Monatsmiete betragen – ohne die als Pauschale oder Vorauszahlung ausgewiesenen Betriebskosten → 3 × 800 € = 2.400 €.", "§ 551 II: Bei einer Geldsumme darf der Mieter in drei gleichen monatlichen Teilzahlungen leisten; die erste ist zu Beginn des Mietverhältnisses fällig. S hat 800 € gezahlt.", "§ 551 IV: Abweichungen zum Nachteil des Mieters sind unwirksam – die Klausel gilt nur bis zur zulässigen Höhe. Kein Verzug → keine fristlose Kündigung.", "Ergebnis: f ist richtig."]}, "P5-31": {"k": "B kann jederzeit k", "w": ["Frage: Kann B ohne Grund kündigen, und was schuldet sie M?", "Werkvertrag (§ 631): Geschuldet ist der Erfolg „gestrichene Räume“.", "§ 648 S. 1: Der Besteller kann bis zur Vollendung jederzeit kündigen, ohne Grund.", "§ 648 S. 2: Der Unternehmer kann dann die vereinbarte Vergütung verlangen, muss sich aber anrechnen lassen, was er infolge der Aufhebung erspart oder durch anderweitige Verwendung seiner Arbeitskraft erwirbt. Ersparnis: Farbe 500 €; anderweitiger Erwerb: keiner → 10.000 − 500 = 9.500 €. Die 5 %-Vermutung (S. 3) ist nur ein Mindestwert für den nicht erbrachten Teil, wenn M nichts weiter darlegt.", "Ergebnis: c ist richtig."]}, "P5-32": {"k": "A muss zahlen, wei", "w": ["Frage: Welcher Vertragstyp liegt vor, und schuldet A die Vergütung trotz Nichtbestehens?", "Abgrenzung: Dienstvertrag (§ 611) = Tätigkeit geschuldet; Werkvertrag (§ 631) = Erfolg geschuldet. Kann der Erfolg von der eigenen Leistung des Schuldners nicht sicher herbeigeführt werden (Prüfungserfolg hängt vom Schüler ab), liegt ein Dienstvertrag nahe.", "N hat sorgfältig unterrichtet → Dienste erbracht. Vergütung ist nach Leistung der Dienste fällig (§ 614).", "Mängelrechte wie Minderung gibt es im Dienstvertrag nicht. Bei schlechter Leistung kommt allenfalls Schadensersatz (§ 280) in Betracht – hier liegt keine Pflichtverletzung vor.", "Ergebnis: a ist richtig."]}, "P5-33": {"k": "A kann binnen 14 T", "w": ["Frage: Kann A den Darlehensvertrag widerrufen, obwohl sie ihn in der Bank geschlossen hat?", "Verbraucherdarlehensvertrag (§ 491): Darlehensgeber Unternehmer (Bank), Darlehensnehmerin Verbraucherin (§ 13), entgeltlich. Form: schriftlich (§ 492) – gewahrt.", "§ 495 I: Dem Darlehensnehmer steht ein Widerrufsrecht nach § 355 zu – unabhängig vom Ort des Vertragsschlusses.", "Frist: 14 Tage (§ 355 II 1), Beginn mit Vertragsschluss, aber nicht bevor A die Pflichtangaben erhalten hat. 3. März → Widerruf am 12. März rechtzeitig. Folge: Rückabwicklung – A zahlt das Darlehen samt Zinsen für die Zeit der Nutzung zurück.", "Ergebnis: e ist richtig."]}, "P5-34": {"k": "Die Abo-Klausel is", "w": ["Frage: Ist die Abo-Pflicht Vertragsbestandteil geworden?", "AGB (§ 305 I): vorformuliert für viele Verträge, von H gestellt. Einbeziehung (§ 305 II): Hinweis und Möglichkeit der Kenntnisnahme – per Häkchen gegeben.", "§ 305c I: Klauseln, die nach den Umständen so ungewöhnlich sind, dass der Vertragspartner mit ihnen nicht zu rechnen braucht, werden nicht Vertragsbestandteil. Eine 24-monatige kostenpflichtige Abo-Pflicht beim Druckerkauf, versteckt unter „Datenschutz“, ist überraschend. § 305c I gilt auch gegenüber Unternehmern.", "Rechtsfolge (§ 306 I): Der Vertrag bleibt im Übrigen wirksam – F behält den Drucker zum vereinbarten Preis, ohne Abo.", "Ergebnis: d ist richtig."]}, "P5-35": {"k": "V kann nicht wider", "w": ["Frage: Hat V beim individuell konfigurierten Tisch ein Widerrufsrecht?", "Fernabsatzvertrag (§ 312c) zwischen Unternehmer und Verbraucher → grundsätzlich Widerrufsrecht (§ 312g I).", "Ausnahme § 312g II Nr. 1: Kein Widerrufsrecht bei Waren, die nicht vorgefertigt sind und für deren Herstellung eine individuelle Auswahl oder Bestimmung durch den Verbraucher maßgeblich ist oder die eindeutig auf seine persönlichen Bedürfnisse zugeschnitten sind.", "Individuelle Maße, Materialwahl und Gravur mit Kindernamen → Ausnahme greift. Der Grund für den Widerruf (Farbton) spielt keine Rolle.", "Ergebnis: b ist richtig."]}, "P5-36": {"k": "Die Anfechtung ist", "w": ["Frage: Kann E ihr Angebot wegen des Rechenfehlers anfechten?", "Anfechtungsgründe: § 119 I (Inhalts- oder Erklärungsirrtum), § 119 II (Eigenschaftsirrtum), § 120, § 123.", "E wollte „18.000 €“ erklären und hat es erklärt – Wille und Erklärung stimmen überein. Der Fehler liegt in der vorgelagerten Berechnung → Kalkulationsirrtum. Bleibt die Kalkulation intern (verdeckt), ist er ein unbeachtlicher Motivirrtum.", "Ausnahmen nur, wenn der Vertragspartner den Fehler erkennt und den Vertrag treuwidrig durchsetzt (§ 242) – B hatte keinen Anlass zu Zweifeln.", "Ergebnis: f – Anfechtung unwirksam, Vertrag zu 18.000 €."]}, "P5-37": {"k": "Rechtzeitig: Bei D", "w": ["Frage: Ist die Anfechtung wegen Drohung im April des Folgejahres noch rechtzeitig?", "Anfechtungsgrund: widerrechtliche Drohung (§ 123 I Alt. 2). Widerrechtlich wegen der Zweck-Mittel-Relation: Druck mit einer Strafanzeige, die mit der verlangten Mieterhöhung in keinem Zusammenhang steht.", "Frist (§ 124 I): ein Jahr. Beginn bei Drohung: mit dem Zeitpunkt, in dem die Zwangslage aufhört (§ 124 II 1) – nicht mit der Erklärung. § 121 (unverzüglich) gilt nicht.", "Die Zwangslage endete frühestens Ende Juni, spätestens mit V's Wegzug im Juli → Frist läuft bis Juni/Juli des Folgejahres. April liegt davor. § 122 greift bei § 123 nicht.", "Ergebnis: c ist richtig."]}, "P5-38": {"k": "I muss zahlen, wei", "w": ["Frage: Muss I die Bestellung des G gegen sich gelten lassen, obwohl er nie Vollmacht erteilt hat?", "Stellvertretung (§ 164 I): G handelte im Namen des Betriebs. Eine ausdrückliche Vollmacht (§ 167) fehlt.", "Duldungsvollmacht (Rechtsschein): Der Vertretene weiß, dass ein anderer für ihn als Vertreter auftritt, und lässt es geschehen; der Geschäftspartner darf das nach Treu und Glauben so verstehen, dass Vollmacht besteht. I wusste seit einem Jahr davon, bezahlte alle Rechnungen; H war gutgläubig.", "Folge: I wird so behandelt, als hätte er Vollmacht erteilt. Ein Streit mit G ändert nichts, solange H nichts davon weiß.", "Ergebnis: a ist richtig."]}});
window.dispatchEvent(new Event('wpr-data'));
})();
